"""Create bilingual Word guides using standard-library Office Open XML only."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape
import re

OUT = Path(__file__).resolve().parent
W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
NS = f'xmlns:w="{W}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"'

def para(text='', style='Normal', page=False):
    prop = f'<w:pStyle w:val="{style}"/>' + ('<w:pageBreakBefore/>' if page else '')
    runs = ''.join('<w:r><w:t xml:space="preserve">'+escape(line)+'</w:t></w:r>' + ('<w:r><w:br/></w:r>' if i < len(text.split('\n'))-1 else '') for i,line in enumerate(text.split('\n')))
    return f'<w:p><w:pPr>{prop}</w:pPr>{runs}</w:p>'

class Guide:
    def __init__(self, title, subtitle, filename):
        self.title, self.filename = title, filename
        self.body = [para('HONEYTRACE', 'Kicker'), para(title, 'Title'), para(subtitle, 'Subtitle'),
            para('English + မြန်မာ Unicode', 'Subtitle'),
            para('Implementation reference: Git commit 4d9780925cfda0b35070e54eca163dba9d86dd98\nPrepared: 8 September 2026\nRepository: https://github.com/RayZDShit/honeytrace', 'Small'),
            para('Scope: the implemented local HoneyTrace project. This guide explains operation and analysis; it does not provide attacker-side instructions.', 'Callout'),
            para('ဤစာတမ်းသည် လက်ရှိ HoneyTrace project ၏ လုပ်ဆောင်ပုံကို ရှင်းပြထားခြင်းဖြစ်သည်။ စနစ်အသုံးပြုခြင်းနှင့် ခွဲခြမ်းစိတ်ဖြာခြင်းကိုသာ ဖော်ပြပြီး တိုက်ခိုက်သူဘက်မှ လုပ်ဆောင်ရန် ညွှန်ကြားချက်များ မပါဝင်ပါ။', 'Callout')]
        self.headings=[]
        self.cover_length = len(self.body)
    def chapter(self, en, my):
        self.headings.append((en,my))
        self.body += [para(en, 'Heading1', True), para(my, 'Heading2')]
    def section(self, en, my):
        self.body += [para(en, 'Heading2'), para(my, 'Heading3')]
    def pair(self, en, my):
        self.body += [para('ENGLISH', 'Language'), para(en), para('မြန်မာ', 'Language'), para(my)]
    def note(self,en,my):
        self.body += [para(en,'Callout'),para(my,'Callout')]
    def code(self,text):
        for line in text.splitlines(): self.body.append(para(line,'Code'))
    def table(self, headers, rows, widths=None):
        widths = widths or [int(9500/len(headers))]*len(headers)
        xml=['<w:tbl><w:tblPr><w:tblW w:w="9500" w:type="dxa"/><w:tblLayout w:type="fixed"/><w:tblBorders>'+''.join(f'<w:{x} w:val="single" w:sz="4" w:color="DCE2E7"/>' for x in ['top','left','bottom','right','insideH','insideV'])+'</w:tblBorders><w:tblCellMar><w:top w:w="90" w:type="dxa"/><w:left w:w="110" w:type="dxa"/><w:bottom w:w="90" w:type="dxa"/><w:right w:w="110" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>'+''.join(f'<w:gridCol w:w="{n}"/>' for n in widths)+'</w:tblGrid>']
        for i,row in enumerate([headers]+rows):
            xml.append('<w:tr><w:trPr><w:cantSplit/>'+('<w:tblHeader/>' if i==0 else '')+'</w:trPr>')
            for j,cell in enumerate(row):
                shade='152D3B' if i==0 else ('F2F5F7' if i%2 else 'FFFFFF')
                xml.append(f'<w:tc><w:tcPr><w:tcW w:w="{widths[j]}" w:type="dxa"/><w:shd w:fill="{shade}"/></w:tcPr>'+para(str(cell),'TableHead' if i==0 else 'TableText')+'</w:tc>')
            xml.append('</w:tr>')
        self.body.append(''.join(xml)+'</w:tbl>')
        self.body.append(para())
    def save(self):
        contents=[para('Reading map / ဖတ်ရှုရန် လမ်းညွှန်','Heading1',True),para('Every section places English first and its Burmese explanation immediately after it. Technical identifiers remain in English so they match the code. Use Word’s Navigation Pane to jump between chapters.','Small'),para('အပိုင်းတိုင်းတွင် အင်္ဂလိပ်ရှင်းလင်းချက်နောက်၌ မြန်မာရှင်းလင်းချက်ကို ထည့်ထားသည်။ Code နှင့် တိုက်ဆိုင်စစ်ဆေးနိုင်ရန် နည်းပညာအမည်များကို English အတိုင်းထားသည်။ Word ၏ Navigation Pane မှ အခန်းများသို့ သွားနိုင်သည်။','Small')]
        for en,my in self.headings: contents.append(para(en+' / '+my,'Contents'))
        # Insert navigation before the first numbered chapter, after the cover.
        body=''.join(self.body[:self.cover_length]+contents+self.body[self.cover_length:])
        sect='<w:sectPr><w:headerReference w:type="default" r:id="rIdHeader"/><w:footerReference w:type="default" r:id="rIdFooter"/><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1080" w:right="1203" w:bottom="1080" w:left="1203" w:header="450" w:footer="450"/></w:sectPr>'
        document=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document {NS}><w:body>{body}{sect}</w:body></w:document>'
        def style(id,size=22,color='253744',bold=False,extra='',based='Normal'):
            props = {match.group(1):match.group(0) for match in re.finditer(r'<w:(\w+)\b[^>]*/>',extra)}
            props.setdefault('spacing','<w:spacing w:after="140" w:line="300" w:lineRule="auto"/>')
            ordered = ''.join(props.get(name,'') for name in ['keepNext','pageBreakBefore','shd','spacing','ind','outlineLvl'])
            return f'<w:style w:type="paragraph" w:styleId="{id}"><w:name w:val="{id}"/>'+('' if id=='Normal' else f'<w:basedOn w:val="{based}"/>')+f'<w:pPr>{ordered}</w:pPr><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Myanmar Text" w:eastAsia="Myanmar Text" w:cs="Myanmar Text"/>'+('<w:b/><w:bCs/>' if bold else '')+f'<w:color w:val="{color}"/><w:sz w:val="{size}"/><w:szCs w:val="{size}"/><w:lang w:val="en-US" w:eastAsia="my-MM" w:bidi="my-MM"/></w:rPr></w:style>'
        styles=f'<?xml version="1.0" encoding="UTF-8"?><w:styles {NS}><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Myanmar Text" w:cs="Myanmar Text"/><w:sz w:val="22"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:widowControl/></w:pPr></w:pPrDefault></w:docDefaults>'
        styles+=style('Normal')+style('Title',44,'152D3B',True,'<w:keepNext/><w:spacing w:before="600" w:after="300"/>')+style('Subtitle',26,'536674')+style('Kicker',24,'A06A12',True)
        for n,size in [(1,30),(2,25),(3,22)]: styles+=style(f'Heading{n}',size,'152D3B',True,f'<w:keepNext/><w:outlineLvl w:val="{n-1}"/>')
        styles+=style('Language',17,'A06A12',True,'<w:keepNext/>')+style('Small',19,'536674')+style('Contents',20)+style('Callout',21,'152D3B',False,'<w:shd w:fill="FFF3D8"/><w:ind w:left="140" w:right="140"/>')+style('Code',18,'152D3B',False,'<w:shd w:fill="F2F5F7"/><w:spacing w:after="40"/>')+style('TableText',19)+style('TableHead',19,'FFFFFF',True)+ '</w:styles>'
        types='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>'+''.join(f'<Override PartName="/word/{part}.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.{kind}+xml"/>' for part,kind in [('document','document.main'),('styles','styles'),('settings','settings'),('header1','header'),('footer1','footer')])+'<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/></Types>'
        relbase='http://schemas.openxmlformats.org/package/2006/relationships'
        rels=f'<Relationships xmlns="{relbase}"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/><Relationship Id="rIdCore" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>'
        docrels=f'<Relationships xmlns="{relbase}">'+''.join(f'<Relationship Id="{rid}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/{kind}" Target="{name}.xml"/>' for rid,kind,name in [('rIdStyles','styles','styles'),('rIdSettings','settings','settings'),('rIdHeader','header','header1'),('rIdFooter','footer','footer1')])+'</Relationships>'
        header=f'<w:hdr {NS}>'+para('HONEYTRACE  |  '+self.title,'Small')+'</w:hdr>'
        footer=f'<w:ftr {NS}><w:p><w:pPr><w:jc w:val="right"/></w:pPr><w:r><w:t>HoneyTrace • </w:t></w:r><w:fldSimple w:instr="PAGE"><w:r><w:t>1</w:t></w:r></w:fldSimple><w:r><w:t> / </w:t></w:r><w:fldSimple w:instr="NUMPAGES"><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p></w:ftr>'
        core='<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>'+escape(self.title)+'</dc:title><dc:creator>HoneyTrace Project Documentation</dc:creator><dc:description>English and Burmese implementation guide</dc:description></cp:coreProperties>'
        files={'[Content_Types].xml':types,'_rels/.rels':rels,'word/document.xml':document,'word/styles.xml':styles,'word/settings.xml':f'<w:settings {NS}><w:updateFields w:val="true"/></w:settings>','word/_rels/document.xml.rels':docrels,'word/header1.xml':header,'word/footer1.xml':footer,'docProps/core.xml':core}
        path=OUT/self.filename
        with ZipFile(path,'w',ZIP_DEFLATED) as z:
            for name,data in files.items(): z.writestr(name,data.encode('utf-8'))
        print(f'{path}: {len(self.headings)} chapters; {len(document):,} XML characters')

tech = Guide('How HoneyTrace Works', 'Detailed technical guide / အသေးစိတ် နည်းပညာရှင်းလင်းချက်', 'HoneyTrace_Technical_Guide_EN_MY.docx')
tech.chapter('1. Purpose, scope and terminology','ရည်ရွယ်ချက်၊ အကျုံးဝင်မှုနှင့် အခြေခံအဓိပ္ပာယ်များ')
tech.pair('HoneyTrace is a self-built SSH honeypot and behavioral-analysis application. It offers a decoy SSH service, records interaction events, groups related activity, extracts numerical features, assigns rule and model labels, and presents evidence through an authenticated analyst dashboard. Its main contribution is the complete path from network interaction to an investigation record—not a claim that it invents SSH or replaces every enterprise security product.', 'HoneyTrace သည် ကိုယ်ပိုင်ရေးသားထားသော SSH honeypot နှင့် အပြုအမူဆိုင်ရာ ခွဲခြမ်းစိတ်ဖြာစနစ်ဖြစ်သည်။ လှည့်စားရန် SSH service တစ်ခုဖွင့်ထားပြီး ဝင်ရောက်ဆက်သွယ်မှုများကို မှတ်တမ်းတင်သည်။ ဆက်စပ်လုပ်ဆောင်ချက်များကို အုပ်စုဖွဲ့၊ ကိန်းဂဏန်းအချက်များ ထုတ်ယူ၊ rule နှင့် model ဖြင့် အမျိုးအစားခွဲပြီး login လိုအပ်သည့် dashboard တွင် သက်သေများ ပြသသည်။ အဓိကတန်ဖိုးမှာ network ဆက်သွယ်မှုမှ စုံစမ်းစစ်ဆေးရေးမှတ်တမ်းအထိ အစအဆုံးချိတ်ဆက်ထားခြင်းဖြစ်ပြီး SSH ကို အသစ်တီထွင်ထားခြင်း သို့မဟုတ် လုပ်ငန်းသုံး security product အားလုံးကို အစားထိုးနိုင်ခြင်း မဟုတ်ပါ။')
tech.table(['Term','Meaning / အဓိပ္ပာယ်'],[
('Honeypot','A decoy service used to observe interactions. / ဝင်ရောက်မှုများကို လေ့လာရန် ရည်ရွယ်ထားသော အတုဝန်ဆောင်မှု။'),
('Sensor','The process accepting SSH connections and producing events. / SSH ချိတ်ဆက်မှုလက်ခံပြီး event ထုတ်ပေးသည့် process။'),
('Event','One observation, such as a connection, login result or command submission. / ချိတ်ဆက်မှု၊ login ရလဒ် သို့မဟုတ် command ပေးပို့မှုတစ်ခု၏ မှတ်တမ်း။'),
('Native session','One actual SSH connection, identified by a random ID. / SSH connection တစ်ခုကို သတ်မှတ်ပေးထားသော ID နှင့် ဆက်သွယ်မှု။'),
('Behavioral session','A time-grouped burst which may include multiple SSH connections from one source and sensor. / source နှင့် sensor တူသည့် connection များကို အချိန်အလိုက် ပေါင်းထားသော လုပ်ဆောင်မှုအုပ်စု။'),
('Incident','A persistent investigation record generated for high/critical live classifications. / အန္တရာယ်အဆင့် high သို့မဟုတ် critical ဖြစ်သော live classification မှ ဖန်တီးသည့် စုံစမ်းစစ်ဆေးရေးမှတ်တမ်း။'),
('Pseudo-label','A label produced by rules, not independently reviewed truth. / လွတ်လပ်သော ကျွမ်းကျင်သူအတည်ပြုချက်မဟုတ်ဘဲ rule မှ ထုတ်ပေးသော အညွှန်း။')],[2300,7200])
tech.note('This is a live, lab-oriented implementation with simulated command responses. “Real connection” and “real operating-system execution” are different things.','ဤစနစ်သည် အမှန်တကယ် connection လက်ခံနိုင်သော်လည်း command အဖြေများကို အတုဖန်တီးထားသည့် lab အသုံးပြုစနစ်ဖြစ်သည်။ “အမှန်တကယ် ချိတ်ဆက်ခြင်း” နှင့် “host operating system တွင် command အမှန်တကယ်လုပ်ဆောင်ခြင်း” ကို ခွဲခြားရမည်။')

tech.chapter('2. Architecture and trust boundaries','ဖွဲ့စည်းပုံနှင့် ယုံကြည်မှုနယ်နိမိတ်များ')
tech.table(['Stage','Data movement / အချက်အလက်စီးဆင်းမှု'],[
('1 · Network','SSH client → local/private sensor on port 2222. / SSH client မှ port 2222 ရှိ sensor သို့။'),
('2 · Capture','AsyncSSH callbacks → bounded in-memory queue. / AsyncSSH callback မှ memory queue သို့။'),
('3 · Persistence','Worker → normalized events in SQLite. / Worker မှ ပုံစံတူပြောင်းထားသော event များကို SQLite တွင်သိမ်း။'),
('4 · Analysis','Source/time grouping → 31 features → rule label → optional saved-model prediction. / source နှင့်အချိန်အလိုက် အုပ်စုဖွဲ့ပြီး feature 31 ခု၊ rule၊ saved model ဖြင့်ခွဲခြား။'),
('5 · Investigation','High/critical result → grouped incident. / high သို့မဟုတ် critical ရလဒ်မှ incident ဖန်တီး။'),
('6 · Presentation','Flask/Waitress API → authenticated browser dashboard, normally port 5000. / Flask/Waitress API မှ login ဝင်ထားသော browser dashboard သို့။')],[2000,7500])
tech.pair('Two long-running processes normally operate: the SSH sensor and the dashboard. They share one configured SQLite database. The browser is only a viewer and analyst interface: closing it does not stop the sensor. The sensor accepts untrusted input. The virtual terminal boundary separates that input from real host commands and files; the dashboard authentication boundary separates stored evidence from anonymous viewers.', 'ပုံမှန်အားဖြင့် SSH sensor နှင့် dashboard ဟူသော process နှစ်ခု သီးခြားအလုပ်လုပ်ပြီး သတ်မှတ်ထားသော SQLite database တစ်ခုတည်းကို မျှဝေအသုံးပြုသည်။ Browser သည် ပြသခြင်းနှင့် စုံစမ်းမှတ်တမ်းရေးခြင်းအတွက်သာ ဖြစ်သဖြင့် browser ပိတ်ခြင်းက sensor ကို မရပ်စေပါ။ Sensor က မယုံကြည်ရသော input ကို လက်ခံသည်။ Virtual terminal နယ်နိမိတ်သည် ထို input ကို host ၏ command နှင့် file များမှ ခွဲထားပြီး dashboard login နယ်နိမိတ်သည် မှတ်တမ်းများကို အမည်မသိကြည့်ရှုသူများမှ ကာကွယ်ပေးသည်။')
tech.pair('AsyncSSH supplies SSH protocol and cryptographic transport. Flask supplies routing and session integration; Waitress serves HTTP. SQLite stores data, NumPy and scikit-learn support classification, joblib stores the trained artifact, and local Chart.js draws the activity chart. Using these libraries is normal software engineering. HoneyTrace’s own code defines the deception behavior, data pipeline, classification rules, integration and analyst workflow.', 'AsyncSSH က SSH protocol နှင့် encrypted transport ကို ပံ့ပိုးသည်။ Flask က route နှင့် login session ဆိုင်ရာလုပ်ဆောင်ချက်များ၊ Waitress က HTTP server ကို ပံ့ပိုးသည်။ SQLite က data သိမ်း၊ NumPy နှင့် scikit-learn က model ဆိုင်ရာတွက်ချက်၊ joblib က model သိမ်း၊ local Chart.js က chart ဆွဲသည်။ Library အသုံးပြုခြင်းသည် ပုံမှန် software engineering ဖြစ်သည်။ HoneyTrace ၏ ကိုယ်ပိုင် code သည် အတု service အပြုအမူ၊ data pipeline၊ rule များ၊ အစိတ်အပိုင်းချိတ်ဆက်မှုနှင့် analyst workflow ကို သတ်မှတ်ထားသည်။')

tech.chapter('3. SSH connection lifecycle','SSH ချိတ်ဆက်မှု၏ အဆင့်ဆင့်လုပ်ဆောင်ပုံ')
tech.pair('Starting manage.py honeypot initializes the schema, loads or creates instance/ssh_host_key, and binds AsyncSSH to 127.0.0.1:2222 by default. This key identifies the sensor to SSH clients; it is not an analyst password and is not the credential-fingerprint key. The advertised SSH server version resembles OpenSSH_8.9p1, but the running implementation is AsyncSSH, not a real Ubuntu OpenSSH service.', 'manage.py honeypot ကို စတင်သောအခါ database schema ကို ပြင်ဆင်၊ instance/ssh_host_key ကို ဖတ် သို့မဟုတ် အသစ်ဖန်တီးပြီး ပုံမှန်အားဖြင့် 127.0.0.1:2222 တွင် AsyncSSH service ကို ဖွင့်သည်။ ဤ key သည် SSH client အတွက် sensor ကို ခွဲခြားသိရှိရန်ဖြစ်ပြီး analyst password သို့မဟုတ် password fingerprint key မဟုတ်ပါ။ ပြသသော server version သည် OpenSSH_8.9p1 နှင့်တူသော်လည်း အမှန်တကယ် run နေသည်မှာ AsyncSSH ဖြစ်ပြီး Ubuntu OpenSSH service အစစ်မဟုတ်ပါ။')
tech.pair('For an admitted connection, HoneySSH creates a random native session ID, records the peer address and source port, adds the connection to its active set, schedules a five-minute close timer, and emits nisec.session.connect. Password validation records success or failure as telemetry. A configured decoy root login can access only the virtual terminal. Other credentials fail. Dashboard accounts are completely separate; there is no preset dashboard password.', 'လက်ခံထားသော connection တစ်ခုအတွက် HoneySSH သည် random native session ID ဖန်တီး၊ peer IP နှင့် source port ကို မှတ်သား၊ active set ထဲထည့်၊ ငါးမိနစ်ပြည့်လျှင် ပိတ်ရန် timer ထားပြီး nisec.session.connect event ထုတ်ပေးသည်။ Password စစ်ဆေးရာတွင် အောင်မြင်မှု သို့မဟုတ် မအောင်မြင်မှုကို event အဖြစ် မှတ်တမ်းတင်သည်။ သတ်မှတ်ထားသော decoy root login သည် virtual terminal ကိုသာ ဝင်နိုင်သည်။ အခြား credential များကို ငြင်းပယ်သည်။ Dashboard account သည် လုံးဝသီးခြားဖြစ်ပြီး ပုံသေ dashboard password မရှိပါ။')
tech.pair('A session channel may request an interactive shell or an individual SSH exec command. PTY requests are accepted; SFTP subsystem requests and TCP forwarding requests are denied. On disconnection, the timer is cancelled, the active set is updated and nisec.session.closed is queued. Stored active-connection records can lag behind memory until the worker processes the corresponding events.', 'Session channel သည် interactive shell သို့မဟုတ် SSH exec command တစ်ခုကို တောင်းနိုင်သည်။ PTY ကို လက်ခံသော်လည်း SFTP subsystem နှင့် TCP forwarding ကို ငြင်းပယ်သည်။ Connection ပိတ်သွားလျှင် timer ဖျက်၊ active set ပြင်ပြီး nisec.session.closed ကို queue ထဲထည့်သည်။ Database ရှိ active connection စာရင်းသည် သက်ဆိုင်ရာ event ကို worker က လုပ်ဆောင်ပြီးမှ ပြောင်းသဖြင့် memory စာရင်းထက် အနည်းငယ်နောက်ကျနိုင်သည်။')
tech.table(['Control','Current default / လက်ရှိ ပုံမှန်တန်ဖိုး'],[
('Concurrent admitted connections','50; configured by NISEC_MAX_HONEYPOT_WORKERS / လက်ခံထားသော connection 50 ခု။'),('Lifetime per connection','300 seconds / စက္ကန့် 300။'),('Authentication timeout','30 seconds / စက္ကန့် 30။'),('Accepted session channels','Up to four during a connection; this is a cumulative counter / connection တစ်ခုအတွင်း စုစုပေါင်း channel လေးခုအထိ။'),('Command input','256 UTF-8 bytes, not necessarily 256 characters / UTF-8 byte 256၊ စာလုံး 256 ဟု မဆိုလို။'),('Commands per channel','At most 100 recorded commands; exceeding the limit closes the channel / channel တစ်ခုလျှင် command 100 အထိ။'),('Queue capacity','4,000 events / event 4,000။'),('Worker batch','Up to 100 events / တစ်ကြိမ်လျှင် event 100 အထိ။')],[3300,6200])

tech.chapter('4. Contained virtual terminal','သီးခြားကန့်သတ်ထားသော အတု terminal')
tech.pair('VirtualShell is a Python object containing a current directory, a dictionary of fake file contents and a set of fake directories. shlex.split parses words and posixpath normalizes simulated paths. Neither operation executes a host shell. A fresh virtual filesystem is created for each accepted terminal channel, so directory changes are not a persistent multi-user filesystem.', 'VirtualShell သည် လက်ရှိ directory၊ file အတုစာသားများပါသော dictionary နှင့် directory အတုစာရင်းတို့ကို ထိန်းသိမ်းထားသည့် Python object ဖြစ်သည်။ shlex.split က စာသားကို စကားလုံးအလိုက်ခွဲပြီး posixpath က အတု path ကို စီစဉ်သည်။ နှစ်ခုစလုံးက host shell ကို မလုပ်ဆောင်ပါ။ Terminal channel တစ်ခုစီအတွက် virtual filesystem အသစ်ဖန်တီးသဖြင့် directory ပြောင်းခြင်းများသည် အမြဲတမ်းသိမ်းထားသော multi-user filesystem မဟုတ်ပါ။')
tech.pair('Supported responses cover pwd, whoami, id, hostname, uname, echo, cd, ls and cat. Fake files include /etc/hostname, /etc/os-release, /etc/passwd and /root/readme.txt. The root name and Linux output are part of the deception, not proof of administrator access to Windows. Requests for network transfers return a simulated error. Unknown commands return “command not found”. Shell pipes, redirection and command substitution are not implemented as host execution.', 'ပံ့ပိုးထားသော အဖြေများမှာ pwd၊ whoami၊ id၊ hostname၊ uname၊ echo၊ cd၊ ls နှင့် cat တို့ဖြစ်သည်။ File အတုများတွင် /etc/hostname၊ /etc/os-release၊ /etc/passwd နှင့် /root/readme.txt ပါဝင်သည်။ root အမည်နှင့် Linux အဖြေများသည် လှည့်စားမှုအစိတ်အပိုင်းသာဖြစ်ပြီး Windows administrator အခွင့်အရေးရရှိခြင်း မဟုတ်ပါ။ Network transfer တောင်းလျှင် အတု error ပြန်ပေးသည်။ မသိသော command များကို command not found ပြန်ပေးသည်။ Pipe၊ redirection နှင့် command substitution တို့ကို host တွင် အမှန်တကယ်လုပ်ဆောင်ရန် မရေးထားပါ။')
tech.pair('The SSH terminal handles CR and LF line endings, echoes printable input for PTY sessions, handles basic backspace, and enforces a byte limit. It records command submissions before producing a simulated answer. The classifier’s existing phrase “commands executed” should therefore be explained as commands submitted to the decoy, not commands executed on the host. The simulation is deliberately limited: command options and exit statuses are not a complete Linux emulation.', 'SSH terminal သည် CR နှင့် LF line ending များ၊ PTY တွင် ရိုက်သည့်စာပြန်ပြခြင်း၊ အခြေခံ backspace နှင့် byte ကန့်သတ်ချက်တို့ကို ကိုင်တွယ်သည်။ အတုအဖြေမပြန်မီ command ပေးပို့မှုကို မှတ်တမ်းတင်သည်။ ထို့ကြောင့် classifier တွင် ပါသော commands executed ဆိုသည့်စကားကို host ပေါ်တွင် အလုပ်လုပ်သွားသည်ဟု မရှင်းပြဘဲ decoy သို့ command ပေးပို့ခဲ့သည်ဟု ရှင်းပြရမည်။ Command option နှင့် exit status အားလုံးကို Linux အစစ်အတိုင်း ပြုလုပ်ထားခြင်း မဟုတ်ပါ။')

tech.chapter('5. Queue, worker, persistence and failure handling','Queue၊ worker၊ သိမ်းဆည်းခြင်းနှင့် ချို့ယွင်းမှုကိုင်တွယ်ပုံ')
tech.pair('Network callbacks enqueue raw event dictionaries with an event ID, UTC timestamp, native session ID, peer IP/port and relevant fields. An asyncio worker removes one item, collects up to 100 available events, then calls persist_batch on a worker thread. This prevents synchronous database and model work from running directly in the SSH callback, although CPU, disk and queue capacity still limit throughput.', 'Network callback များသည် event ID၊ UTC timestamp၊ native session ID၊ peer IP/port နှင့် သက်ဆိုင်ရာ field များပါသော dictionary ကို queue ထဲသို့ ထည့်သည်။ asyncio worker သည် event တစ်ခုယူပြီး ရှိနေသော event များကို 100 အထိစုကာ worker thread ပေါ်တွင် persist_batch ကို ခေါ်သည်။ ထိုသို့ပြုလုပ်ခြင်းက database နှင့် model ဆိုင်ရာအလုပ်ကို SSH callback ထဲတွင် တိုက်ရိုက်စောင့်လုပ်ရခြင်းမှ ခွဲပေးသော်လည်း CPU၊ disk နှင့် queue ပမာဏတို့က throughput ကို ဆက်လက်ကန့်သတ်ထားသည်။')
tech.pair('persist_batch normalizes and stores the events in one database context, updates active_connections for connect/close events, then processes each distinct source address in that batch. It rebuilds the latest relevant behavioral session, applies the saved model if present, and synchronizes incidents. Raw events commit before classification: a model error does not imply that all raw evidence was lost.', 'persist_batch သည် event များကို ပုံစံတူပြောင်း၍ database context တစ်ခုအတွင်း သိမ်းပြီး connect/close event အလိုက် active_connections ကို ပြင်သည်။ ထို့နောက် batch ထဲရှိ source address တစ်ခုစီအတွက် နောက်ဆုံးသက်ဆိုင်ရာ behavioral session ကို ပြန်တွက်၊ model ရှိလျှင် အသုံးပြုပြီး incident ကို ပြင်ဆင်သည်။ Raw event များကို classification မတိုင်မီ commit လုပ်ထားသဖြင့် model error တက်ခြင်းက raw evidence အားလုံး ပျောက်သွားသည်ဟု မဆိုလိုပါ။')
tech.pair('There are three total processing attempts for a failed batch, with short delays before attempts two and three. Deduplication makes repeated event insertion mostly repeat-safe. Exhausted batches increment the dropped counter conservatively, even if raw rows were already committed. Queue-full handling increments the counter and closes that client. The last processing duration is displayed in milliseconds; it is not a measured network-to-screen latency. A later successful batch clears the last error message, while the counter remains for that sensor process.', 'Batch မအောင်မြင်လျှင် စုစုပေါင်း သုံးကြိမ်ကြိုးစားပြီး ဒုတိယနှင့် တတိယကြိမ်မတိုင်မီ အချိန်တိုစောင့်သည်။ Deduplication ကြောင့် event ထပ်ထည့်ခြင်းကို အများအားဖြင့် ကာကွယ်နိုင်သည်။ သုံးကြိမ်လုံးမအောင်မြင်သော batch ကို raw row သိမ်းပြီးဖြစ်နေလျှင်ပင် dropped counter တွင် ကြိုတင်သတိထားသည့်သဘောဖြင့် ထည့်တွက်သည်။ Queue ပြည့်လျှင်လည်း counter တိုးပြီး ထို client ကို ပိတ်သည်။ ပြသသော millisecond သည် နောက်ဆုံး batch လုပ်ဆောင်ချိန်ဖြစ်ပြီး network မှ screen အထိကြာချိန် မဟုတ်ပါ။ နောက် batch အောင်မြင်လျှင် error စာသားရှင်းသွားသော်လည်း process မရပ်မချင်း counter ကျန်နေသည်။')
tech.note('The queue is memory-only. Process crashes can lose queued events. Graceful shutdown attempts a 15-second drain, but there is no durable message broker or exactly-once delivery guarantee.','Queue သည် memory ထဲတွင်သာရှိသည်။ Process ရုတ်တရက်ပိတ်လျှင် မသိမ်းရသေးသော event များ ပျောက်နိုင်သည်။ ပုံမှန်ပိတ်ရာတွင် queue ကို 15 စက္ကန့်အတွင်း အပြီးလုပ်ရန် ကြိုးစားသော်လည်း durable message broker သို့မဟုတ် exactly-once အာမခံချက် မရှိပါ။')

tech.chapter('6. Normalization and credential privacy','Data ပုံစံတူပြောင်းခြင်းနှင့် credential ကိုယ်ရေးလုံခြုံမှု')
tech.pair('ingest.py maps both nisec.* and Cowrie input fields into one event schema. It limits text lengths, converts valid timestamps to UTC, accepts integer port values, stores command text separately, and replaces login messages that could repeat passwords with redacted summaries. A SHA-256 event key is built from source, connection, event type, time, address, port, command, URL and safe message; a unique constraint plus INSERT OR IGNORE prevents identical-key duplicates.', 'ingest.py သည် nisec.* နှင့် Cowrie input field များကို event schema တစ်မျိုးတည်းသို့ ပြောင်းသည်။ စာသားအရှည်ကန့်သတ်၊ မှန်ကန်သော timestamp ကို UTC ပြောင်း၊ integer port ကိုလက်ခံ၊ command စာသားကိုသီးခြားသိမ်းပြီး password ပါနိုင်သော login message ကို redacted summary ဖြင့်အစားထိုးသည်။ Source၊ connection၊ event type၊ အချိန်၊ address၊ port၊ command၊ URL နှင့် safe message တို့မှ SHA-256 event key ထုတ်သည်။ Unique constraint နှင့် INSERT OR IGNORE ကြောင့် key တူ event များ ထပ်မသိမ်းပါ။')
tech.pair('Password analysis stores an HMAC-SHA256 fingerprint using a local random key, a masked preview, length, per-character Shannon entropy and common-password indicator. This enables counting distinct passwords without storing a reusable plaintext password column. It is not reversible encryption. The preview still exposes the first character and length; usernames and original source addresses remain in the database. Commands can contain secrets. The fingerprint key must be backed up consistently with the database, because changing it changes future fingerprints.', 'Password ကို local random key ဖြင့် HMAC-SHA256 fingerprint၊ ဖုံးထားသော preview၊ အရှည်၊ စာလုံးဖြန့်ဝေမှုအပေါ်အခြေခံသော Shannon entropy နှင့် common-password အမှတ်တို့အဖြစ် သိမ်းသည်။ ထို့ကြောင့် ပြန်အသုံးပြုနိုင်သော plaintext password column မသိမ်းဘဲ password မတူညီမှုကို ရေတွက်နိုင်သည်။ ၎င်းသည် ပြန်ဖြည်နိုင်သော encryption မဟုတ်ပါ။ Preview က ပထမစာလုံးနှင့် အရှည်ကို ဖော်ပြနေဆဲဖြစ်ပြီး username နှင့် source IP အစစ်တို့သည် database ထဲတွင် ရှိနေသည်။ Command ထဲတွင်လည်း secret ပါနိုင်သည်။ Fingerprint key ပြောင်းလျှင် နောက်ပိုင်း fingerprint များပြောင်းမည်ဖြစ်၍ database နှင့်အတူ key ကို တစ်သမတ်တည်း backup ယူရမည်။')
tech.pair('Privacy limits matter: raw submitted passwords temporarily exist in process memory before normalization; the database is not encrypted at rest by this code; masked display is not full anonymization. Event-key fields do not include the password or username, so unusually identical login observations at the same timestamp can collide semantically. Malformed timestamps may survive normalization unchanged and later fail session parsing. These are implementation limitations, not protections to claim.', 'Privacy ကန့်သတ်ချက်များကို သိထားရမည်။ Password အစစ်သည် normalization မလုပ်မီ process memory ထဲတွင် ခဏရှိသည်။ ဤ code က database ကို disk ပေါ်တွင် encrypt မလုပ်ပါ။ Screen တွင်ဖုံးခြင်းသည် အပြည့်အဝ anonymization မဟုတ်ပါ။ Event key တွင် password နှင့် username မပါသဖြင့် timestamp နှင့် အခြား field အားလုံးတူသော login များကို တစ်ခုတည်းဟု ယူဆနိုင်သည်။ မှားနေသော timestamp ကို normalization က မပြင်နိုင်လျှင် နောက် session parsing တွင် error ဖြစ်နိုင်သည်။ ဤအချက်များသည် ကန့်သတ်ချက်များဖြစ်ပြီး ကာကွယ်နိုင်စွမ်းဟု မပြောရပါ။')

tech.chapter('7. Behavioral session grouping and stable IDs','အပြုအမူအုပ်စုဖွဲ့ခြင်းနှင့် မပြောင်းလဲသော ID')
tech.pair('Events are ordered by source type, sensor name, source IP and time. A behavioral burst continues while the gap between consecutive events is at most 120 seconds by default. A gap greater than 120 seconds starts a new burst. This is an inactivity-gap rule, not a fixed two-minute time bucket and not the duration of a TCP connection. A burst can last much longer if events keep arriving.', 'Event များကို source type၊ sensor name၊ source IP နှင့် အချိန်အလိုက် စီသည်။ ဆက်တိုက် event နှစ်ခုကြား ကွာချိန်သည် ပုံမှန် 120 စက္ကန့်ထက် မကျော်လျှင် behavioral burst တစ်ခုအဖြစ် ဆက်လက်ယူသည်။ 120 စက္ကန့်ထက်ကျော်လျှင် burst အသစ်စသည်။ ဤစည်းမျဉ်းသည် လှုပ်ရှားမှုမရှိသည့်ကြားချိန်အပေါ် အခြေခံပြီး နှစ်မိနစ်စီ အတိအကျပိုင်းခြင်း သို့မဟုတ် TCP connection ကြာချိန်နှင့် တူခြင်းမဟုတ်ပါ။ Event ဆက်ဝင်နေလျှင် burst တစ်ခုသည် အချိန်ကြာနိုင်သည်။')
tech.pair('For example, observations at 10:00:00, 10:01:30 and 10:03:20 stay together because the gaps are 90 and 110 seconds. An observation at 10:05:21 starts a new burst because the last gap is 121 seconds. Multiple SSH connections can therefore contribute to one brute-force-like pattern. Conversely, shared NAT addresses can merge unrelated people, and changing source IP can split one person’s behavior; an IP is not a verified human identity.', 'ဥပမာ 10:00:00၊ 10:01:30 နှင့် 10:03:20 တွင် event ဖြစ်လျှင် ကြားချိန် 90 နှင့် 110 စက္ကန့်ဖြစ်သောကြောင့် အုပ်စုတစ်ခုတည်းဖြစ်သည်။ 10:05:21 တွင် ထပ်ဖြစ်လျှင် 121 စက္ကန့်ကွာသဖြင့် burst အသစ်ဖြစ်သည်။ ထို့ကြောင့် SSH connection အများအပြားမှ brute-force နှင့်တူသောပုံစံကို အုပ်စုတစ်ခုအဖြစ် မြင်နိုင်သည်။ သို့သော် NAT IP တူသူများကို မှားပေါင်းနိုင်ပြီး IP ပြောင်းသုံးသူတစ်ဦးကို အုပ်စုခွဲသွားနိုင်သည်။ IP သည် လူတစ်ဦး၏ အတည်ပြုထားသော identity မဟုတ်ပါ။')
tech.pair('The session key hashes source type, sensor, IP and the burst’s first timestamp. Live rebuild_identity reads the newest known burst onward and uses an upsert, preserving its numerical session ID while recomputing features. Events link back through analysis_session_id. Database triggers append a session_changes revision on inserts and updates, so model rescoring can update an existing dashboard card even without a new event ID. A full offline manage.py sessions rebuild still deletes and recreates session records; old incident-to-session links may become stale.', 'Session key ကို source type၊ sensor၊ IP နှင့် burst ၏ ပထမ timestamp တို့မှ hash ထုတ်သည်။ Live rebuild_identity သည် နောက်ဆုံးသိထားသော burst မှစ၍ ပြန်ဖတ်ပြီး upsert ဖြင့် feature များ ပြန်တွက်သော်လည်း numerical session ID ကို ထိန်းထားသည်။ Event များသည် analysis_session_id ဖြင့် session သို့ ချိတ်သည်။ Database trigger များက insert/update တိုင်း session_changes revision ထည့်သောကြောင့် event ID အသစ်မရှိလျှင်ပင် model ပြန်တွက်ထားသော card ကို dashboard တွင် ပြောင်းနိုင်သည်။ သို့သော် offline manage.py sessions အပြည့်ပြန်တည်ဆောက်မှုသည် session များကို ဖျက်၍အသစ်ရေးသဖြင့် incident မှ session သို့ အဟောင်းချိတ်ဆက်မှု မမှန်တော့နိုင်ပါ။')

tech.chapter('8. All 31 model features','Model အသုံးပြုသော feature 31 ခု အပြည့်အစုံ')
tech.pair('Features are numerical summaries of a behavioral session, in the exact FEATURE_COLUMNS order. Missing quantities become zero and vectors must contain only finite values. Tree models use these values without a separate normalization scaler. No raw IP, username string or plaintext password is a model input; identity is used for grouping, not as an input feature.', 'Feature များသည် behavioral session ၏ ကိန်းဂဏန်းအနှစ်ချုပ်များဖြစ်ပြီး FEATURE_COLUMNS အစီအစဉ်အတိုင်း model သို့ထည့်သည်။ မရှိသောအချက်ကို သုညထားပြီး vector တွင် finite ကိန်းများသာ ပါရမည်။ Tree model များအတွက် သီးခြား normalization scaler မသုံးထားပါ။ IP အစစ်၊ username စာသားနှင့် plaintext password ကို model input မလုပ်ပါ။ Identity ကို grouping အတွက်သာသုံးသည်။')
features=[
('event_count','All events in the burst.','Burst ထဲရှိ event စုစုပေါင်း။'),('native_session_count','Distinct native SSH/log session IDs.','မတူညီသော native session ID အရေအတွက်။'),('duration_seconds','Last minus first event time, never below zero.','နောက်ဆုံးနှင့် ပထမ event အချိန်ကွာခြားချက်၊ အနည်းဆုံး သုည။'),('connection_count','Recorded connection-open events.','Connection စတင် event အရေအတွက်။'),('login_failures','Failed authentication events.','မအောင်မြင်သော login အရေအတွက်။'),('login_successes','Successful decoy authentication events.','အောင်မြင်သော decoy login အရေအတွက်။'),('login_attempts','Failures plus successes.','မအောင်မြင်မှုနှင့် အောင်မြင်မှု စုစုပေါင်း။'),('success_ratio','Successes / attempts; zero if no attempts.','အောင်မြင်မှု / ကြိုးစားမှု၊ မရှိလျှင် သုည။'),('unique_usernames','Distinct nonempty submitted usernames.','တင်သွင်းသော username မတူညီမှု။'),('unique_passwords','Distinct credential fingerprints.','Credential fingerprint မတူညီမှု။'),('unique_pairs','Distinct username/fingerprint pairs.','Username နှင့် fingerprint အတွဲ မတူညီမှု။'),('unique_pair_ratio','Distinct pairs / attempts.','မတူညီသောအတွဲ / ကြိုးစားမှု။'),('common_username_ratio','Fraction matching the configured common-name list.','Common username စာရင်းနှင့် ကိုက်ညီသော အချိုး။'),('common_password_ratio','Fraction matching the configured common-password list.','Common password စာရင်းနှင့် ကိုက်ညီသော အချိုး။'),('avg_password_length','Mean length across credential-bearing login events.','Password ပါသော login များ၏ ပျမ်းမျှ password အရှည်။'),('avg_password_entropy','Mean character-distribution Shannon entropy; not proven password strength.','စာလုံးဖြန့်ဝေမှု entropy ပျမ်းမျှ၊ password ခိုင်မာမှုအတည်ပြုချက်မဟုတ်။'),('avg_login_interval','Mean seconds between consecutive login events.','ဆက်တိုက် login များကြား ပျမ်းမျှစက္ကန့်။'),('min_login_interval','Smallest login gap, or zero.','အငယ်ဆုံး login ကြားချိန်၊ မရှိလျှင် သုည။'),('max_login_interval','Largest login gap, or zero.','အကြီးဆုံး login ကြားချိန်၊ မရှိလျှင် သုည။'),('std_login_interval','Population standard deviation of login gaps.','Login ကြားချိန်များ၏ population standard deviation။'),('attempts_per_minute','Attempts / max(duration in minutes, 1/60). Duration includes all session events.','ကြိုးစားမှု / max(မိနစ်ဖြင့်ကြာချိန်၊ 1/60)။ ကြာချိန်တွင် session event အားလုံးပါသည်။'),('command_count','Number of nonempty recorded command strings.','စာသားမလွတ်သော command မှတ်တမ်း အရေအတွက်။'),('unique_command_count','Distinct exact command strings.','တိတိကျကျ မတူညီသော command စာသားအရေအတွက်။'),('recon_command_count','Commands containing at least one reconnaissance substring.','Reconnaissance substring အနည်းဆုံးတစ်ခုပါသော command အရေအတွက်။'),('recon_command_ratio','Recon command count / command count.','Recon command အရေအတွက် / command အားလုံး။'),('download_keyword_count','Total matching transfer-related substrings across commands.','Command များအတွင်း transfer keyword ကိုက်ညီမှု စုစုပေါင်း။'),('miner_keyword_count','Total matching miner-related substrings.','Miner ဆိုင်ရာ keyword ကိုက်ညီမှု စုစုပေါင်း။'),('botnet_keyword_count','Total matching botnet-related substrings.','Botnet ဆိုင်ရာ keyword ကိုက်ညီမှု စုစုပေါင်း။'),('download_count','Cowrie upload/download event count; both directions count.','Cowrie upload/download event နှစ်မျိုးလုံး၏ အရေအတွက်။'),('client_version_count','Distinct captured client-version strings.','ဖမ်းယူထားသော client version မတူညီမှု။'),('hassh_count','Distinct captured HASSH fingerprints.','ဖမ်းယူထားသော HASSH fingerprint မတူညီမှု။')]
tech.table(['Feature','Calculation / တွက်ချက်ပုံ'],[(n,e+'\n'+m) for n,e,m in features],[3000,6500])
tech.note('The custom sensor currently does not emit HASSH, client-version or file-transfer events. Those features can be informative for historical Cowrie data but are generally zero for this sensor. Keyword matching is substring-based, not proof of actual malware execution.','လက်ရှိ custom sensor သည် HASSH၊ client-version နှင့် file-transfer event များ မထုတ်ပေးပါ။ ထို feature များသည် Cowrie data တွင် အသုံးဝင်နိုင်သော်လည်း custom sensor အတွက် များသောအားဖြင့် သုညဖြစ်သည်။ Keyword ကို စာသားအပိုင်းအစအဖြစ် ရှာခြင်းသာဖြစ်ပြီး malware အမှန်တကယ် run ခဲ့ကြောင်း သက်သေမဟုတ်ပါ။')

tech.chapter('9. Rule decision order and severity','Rule ဆုံးဖြတ်သည့် အစီအစဉ်နှင့် အန္တရာယ်အဆင့်')
tech.pair('classify evaluates the following rules top to bottom and returns the first match. One session gets one current rule label, even when several behaviors occurred. Severity is mapped from the final category, not calculated from a separate risk-scoring equation. These thresholds are implementation choices, not universal cybersecurity definitions.', 'classify သည် အောက်ပါ rule များကို အပေါ်မှအောက် စစ်ပြီး ပထမဆုံးကိုက်ညီသည့်တစ်ခုကို ပြန်ပေးသည်။ အပြုအမူအမျိုးမျိုးဖြစ်ခဲ့သော်လည်း session တစ်ခုအတွက် လက်ရှိ rule label တစ်ခုသာ ရသည်။ Severity ကို သီးခြား risk equation မတွက်ဘဲ final category အလိုက် သတ်မှတ်သည်။ Threshold များသည် ဤ project ၏ သတ်မှတ်ချက်ဖြစ်ပြီး cybersecurity လောကတစ်ခုလုံး၏ အတိအကျစံသတ်မှတ်ချက် မဟုတ်ပါ။')
rules=[('1 · cryptomining / critical','miner_keyword_count > 0','Miner keyword အနည်းဆုံးတစ်ခု။'),('2 · botnet_activity / critical','botnet_keyword_count > 0','Botnet keyword အနည်းဆုံးတစ်ခု။'),('3 · malware_delivery / critical','download_count > 0 OR download_keyword_count > 0','Transfer event သို့မဟုတ် download keyword ရှိခြင်း။'),('4 · reconnaissance / high','successes > 0 AND commands > 0 AND recon ratio ≥ 0.60','Login အောင်မြင်၊ command ရှိပြီး recon အချိုး 60% နှင့်အထက်။'),('5 · post_exploitation / critical','successes > 0 AND commands > 0','အောင်မြင်သော decoy login နောက် command ပေးပို့ခြင်း။'),('6 · password_spraying / high','failures ≥ 8; users ≥ 5; passwords ≤ max(2, round(attempts × 0.15))','မအောင်မြင်မှု 8 နှင့်အထက်၊ user 5 နှင့်အထက်၊ password အစုနည်းခြင်း။'),('7 · credential_stuffing / high','failures ≥ 8; pair ratio ≥ 0.75; users ≥ 4; passwords ≥ 4','မအောင်မြင်မှု 8 နှင့်အထက်၊ အတွဲအချိုး 75% နှင့်အထက်၊ user/password အမျိုးအစား 4 နှင့်အထက်စီ။'),('8 · brute_force / high','failures ≥ 20 AND attempts/minute ≥ 2','မအောင်မြင်မှု 20 နှင့်အထက်၊ တစ်မိနစ်လျှင် ကြိုးစားမှု 2 နှင့်အထက်။'),('9 · dictionary_attack / medium','failures ≥ 6','မအောင်မြင်မှု 6 နှင့်အထက်။'),('10 · successful_login / medium','successes > 0','အောင်မြင်မှု အနည်းဆုံးတစ်ခု။'),('11 · scanning / low','failures > 0','မအောင်မြင်မှုရှိပြီး အထက် rule မကိုက်။'),('12 · unknown / low','No earlier match','အထက် rule တစ်ခုမျှ မကိုက်။')]
tech.table(['Priority / category','Exact test and explanation / စစ်ဆေးချက်'],[(a,b+'\n'+c) for a,b,c in rules],[3400,6100])
tech.note('“Malware delivery” may mean only that transfer-related text was submitted. “Credential stuffing” describes a pair-diversity heuristic, not proof that credentials were stolen. A connection without login/commands is unknown, not automatically scanning. Explain these labels as indicators requiring review.','Malware delivery သည် transfer ဆိုင်ရာစာသား ပေးပို့ခြင်းမျှသာ ဖြစ်နိုင်သည်။ Credential stuffing သည် credential အတွဲ မတူညီမှုကို အခြေခံသော heuristic ဖြစ်ပြီး ခိုးယူထားသော credential ဖြစ်ကြောင်း အထောက်အထားမဟုတ်ပါ။ Login သို့မဟုတ် command မရှိသော connection ကို scanning ဟု အလိုအလျောက်မသတ်မှတ်ဘဲ unknown သတ်မှတ်သည်။ ဤ label များကို လူကပြန်စစ်ရမည့် indicator အဖြစ် ရှင်းပြပါ။')

tech.chapter('10. Model training, selection and saved inference','Model လေ့ကျင့်ခြင်း၊ ရွေးချယ်ခြင်းနှင့် သိမ်းထားသော model အသုံးပြုခြင်း')
tech.pair('Training reads stored session features and rule labels, excludes unknown, and keeps classes with at least 40 sessions from at least three sensor/IP groups. At least two supported classes are required. Very large classes are capped at 15,000 samples with reproducible random sampling (seed 42); this cap does not make all class sizes equal. A group is sensor name plus source IP, so the same IP appearing at different sensors can belong to different groups.', 'Training သည် သိမ်းထားသော session feature နှင့် rule label ကိုဖတ်၊ unknown ကိုဖယ်ပြီး sensor/IP group အနည်းဆုံးသုံးခုမှ session 40 နှင့်အထက်ရှိသော class များကို ရွေးသည်။ Class အနည်းဆုံးနှစ်မျိုး လိုသည်။ Class အလွန်ကြီးလျှင် seed 42 ဖြင့် ပြန်ထုတ်နိုင်သော random sample 15,000 အထိသာယူသည်။ ထို့ကြောင့် class အားလုံး အရွယ်အစားတူသွားခြင်း မဟုတ်ပါ။ Group သည် sensor name နှင့် source IP တွဲဖြစ်သဖြင့် sensor မတူသော IP တူများသည် group မတူနိုင်သည်။')
tech.pair('StratifiedGroupKFold creates an outer held-out fold using up to five splits subject to class-group support. Only the first outer split is used as the protected holdout. Inside the training partition, up to three grouped folds compare Extra Trees and Random Forest by mean macro-F1. Both use 240 trees. Extra Trees uses max_features=0.75 and balanced class weights; Random Forest uses sqrt features and balanced_subsample weights. The selected estimator is fitted on the training partition, evaluated once on the holdout, and that fitted estimator is saved—not refitted on the combined train and holdout data.', 'StratifiedGroupKFold သည် class-group ပံ့ပိုးမှုပေါ်မူတည်၍ split ငါးခုအထိသုံးပြီး outer holdout တစ်ခု ဖန်တီးသည်။ ပထမ outer split ကိုသာ protected holdout အဖြစ် သုံးသည်။ Training partition အတွင်း grouped fold သုံးခုအထိဖြင့် Extra Trees နှင့် Random Forest ကို mean macro-F1 အလိုက် နှိုင်းယှဉ်သည်။ နှစ်ခုလုံး tree 240 သုံးသည်။ Extra Trees တွင် max_features=0.75 နှင့် balanced weight၊ Random Forest တွင် sqrt feature နှင့် balanced_subsample weight သုံးသည်။ ရွေးထားသော estimator ကို training partition ဖြင့် fit လုပ်၊ holdout ပေါ်တွင် တစ်ကြိမ်စစ်ပြီး ထို estimator ကို သိမ်းသည်။ Training နှင့် holdout ပေါင်း၍ ပြန် fit မလုပ်ပါ။')
tech.pair('The joblib artifact stores the estimator, model version, training timestamp, feature order and model classes. SQLite model_runs stores metrics, feature importance and run metadata. Daily live processing reloads the saved artifact and calls predict_proba; it does not train online. The class with the largest score becomes predicted_label. If that score is at least 0.55, it becomes final_label; otherwise the rule label remains final. Severity is then mapped from final_label. Unknown-rule sessions are explicitly left unscored.', 'Joblib artifact ထဲတွင် estimator၊ version၊ training အချိန်၊ feature အစီအစဉ်နှင့် class များ သိမ်းသည်။ SQLite model_runs ထဲတွင် metric၊ feature importance နှင့် run အချက်အလက် သိမ်းသည်။ နေ့စဉ် live processing တွင် saved artifact ကိုဖတ်ပြီး predict_proba ခေါ်ခြင်းသာဖြစ်၍ online training မလုပ်ပါ။ Score အများဆုံး class သည် predicted_label ဖြစ်သည်။ Score 0.55 နှင့်အထက်လျှင် final_label အဖြစ်ယူပြီး မပြည့်လျှင် rule label ကို ဆက်ယူသည်။ ထို့နောက် final_label အလိုက် severity သတ်မှတ်သည်။ Rule အရ unknown ဖြစ်သော session များကို model score မတွက်ပါ။')
tech.note('Code-level caveat: all non-unknown rule sessions are passed to the classifier; it does not first verify that their rule category was represented in training. A model may therefore override an unsupported rule category with a supported one, or lower severity. The rule reason is not a model-specific explanation. There is no calibrated uncertainty estimate or general out-of-distribution detector.','Code အရ သတိပြုရန်မှာ unknown မဟုတ်သော session အားလုံးကို classifier သို့ထည့်ပြီး rule category သည် training တွင် ပါခဲ့သလားဟု အရင်မစစ်ပါ။ ထို့ကြောင့် training မပါသော rule category ကို model သိသော category ဖြင့် အစားထိုးနိုင်သလို severity လည်း လျော့သွားနိုင်သည်။ Rule reason သည် model ဆုံးဖြတ်ချက်အတွက် သီးသန့်ရှင်းလင်းချက် မဟုတ်ပါ။ Calibrated uncertainty သို့မဟုတ် ယေဘုယျ out-of-distribution detector မရှိပါ။')

tech.chapter('11. Reading the evaluation honestly','Evaluation ရလဒ်ကို မှန်ကန်စွာ နားလည်ခြင်း')
tech.pair('The repository README records a previous local run: 83 Cowrie JSON members from 10 sensors, 3,308,028 normalized events, 47,855 behavioral sessions, 13,429 unique source addresses, Extra Trees selected, 22,137 training sessions and 5,534 holdout sessions. It reports 99.44% balanced accuracy and 99.68% macro-F1 for model version 20260901T180127Z. These are the recorded reference results, not a fresh measurement made for this document and not a guarantee for the self-built sensor.', 'Repository README တွင် ယခင် local run ၏ ရလဒ်အဖြစ် sensor 10 ခုမှ Cowrie JSON member 83 ခု၊ normalized event 3,308,028 ခု၊ behavioral session 47,855 ခု၊ source address 13,429 ခု၊ ရွေးထားသော Extra Trees၊ training session 22,137 ခုနှင့် holdout session 5,534 ခုဟု မှတ်တမ်းတင်ထားသည်။ Model version 20260901T180127Z အတွက် balanced accuracy 99.44% နှင့် macro-F1 99.68% ဖော်ပြထားသည်။ ဤကိန်းများသည် ရှိပြီးသား reference ရလဒ်များဖြစ်ပြီး ဤစာတမ်းအတွက် အသစ်တိုင်းထားခြင်း သို့မဟုတ် ကိုယ်ပိုင် sensor အတွက် အာမခံခြင်း မဟုတ်ပါ။')
tech.table(['Metric','Interpretation / အဓိပ္ပာယ်'],[
('Accuracy','Correct labels / all evaluated examples; can hide minority-class errors. / မှန်သော label အချိုး၊ class နည်းသောအုပ်စု၏အမှားကို ဖုံးကွယ်နိုင်။'),('Precision','Of examples predicted as a class, how many match its reference label? / Class တစ်ခုဟု ခန့်မှန်းထားသည့်ထဲမှ reference နှင့် ကိုက်ညီမှုအချိုး။'),('Recall','Of actual reference examples of a class, how many were found? / Reference class ထဲမှ model က မှန်စွာရှာတွေ့မှုအချိုး။'),('Balanced accuracy','Mean class recall; gives each class equal weight. / Class recall များ၏ ပျမ်းမျှ၊ class တစ်ခုစီကို အလေးချိန်တူပေး။'),('Macro-F1','Mean of per-class F1; F1 = 2PR/(P+R). / Class တစ်ခုစီ၏ F1 ပျမ်းမျှ၊ F1 = 2PR/(P+R)။'),('Confusion matrix','Reference rows versus predicted columns reveal category confusions. / Reference row နှင့် prediction column အလိုက် မှားခွဲသည့် class များကိုမြင်ရ။'),('Feature importance','Tree split-based relative importance, not causality or a per-incident explanation. / Tree split ဆိုင်ရာ အရေးပါမှု၊ အကြောင်းရင်းအတည်ပြုချက် သို့မဟုတ် incident တစ်ခုချင်းရှင်းလင်းချက်မဟုတ်။')],[2600,6900])
tech.pair('The central limitation is target construction: rules generate the target labels from the same behavioral features that the model receives. A high score can indicate that the model learned the rule boundaries. Group separation reduces overlap within sensor/IP identities, but does not remove rule-derived target circularity, campaign similarity, or historical-to-live domain shift. Do not present 99% as “99% of real attacks detected”. Appropriate future evaluation includes independently reviewed labels, a chronological holdout, an unseen-sensor holdout, per-class error review and measured end-to-end latency under controlled load.', 'အဓိကကန့်သတ်ချက်မှာ target label တည်ဆောက်ပုံဖြစ်သည်။ Model သို့ထည့်သော behavioral feature များကိုပင် rule က အသုံးပြု၍ target label ထုတ်သည်။ ထို့ကြောင့် score မြင့်ခြင်းသည် model က rule နယ်နိမိတ်ကို ကောင်းစွာသင်ယူထားခြင်း ဖြစ်နိုင်သည်။ Group ခွဲခြင်းက sensor/IP identity အတွင်း ထပ်နေမှုကို လျှော့သော်လည်း rule-derived label ကိုပြန်သင်ယူခြင်း၊ campaign ဆင်တူမှုနှင့် historical-to-live domain shift ကို မဖယ်ရှားနိုင်ပါ။ 99% ကို တကယ့်တိုက်ခိုက်မှု 99% ဖမ်းနိုင်သည်ဟု မပြောပါနှင့်။ နောက်ပိုင်းတွင် လွတ်လပ်စွာစစ်ထားသော label၊ အချိန်အလိုက် holdout၊ မမြင်ဖူးသော sensor holdout၊ class အလိုက်အမှားစစ်ခြင်းနှင့် controlled load အောက်ရှိ end-to-end latency တိုင်းခြင်းတို့ လိုသည်။')

tech.chapter('12. Live monitoring and change cursors','Live monitoring နှင့် ပြောင်းလဲမှု cursor များ')
tech.pair('The dashboard polls /api/live every two seconds, rather than receiving WebSocket pushes. Its first request loads a bounded recent snapshot and records the current maximum event ID and session revision. Later requests ask for events after the event cursor and session changes after the revision cursor. Separate cursors are necessary because a model update can change a session without inserting a new raw event. The response carries has_more; the browser requests backlog batches at roughly 100-millisecond intervals until caught up.', 'Dashboard သည် WebSocket push လက်ခံခြင်းမဟုတ်ဘဲ နှစ်စက္ကန့်တစ်ကြိမ် /api/live ကို မေးသည်။ ပထမ request တွင် အရေအတွက်ကန့်သတ်ထားသော လတ်တလော snapshot ကိုယူပြီး လက်ရှိအမြင့်ဆုံး event ID နှင့် session revision ကို မှတ်ထားသည်။ နောက် request များတွင် event cursor နောက်ရှိ event နှင့် revision cursor နောက်ရှိ session change များကို တောင်းသည်။ Model update ကြောင့် raw event အသစ်မရှိဘဲ session ပြောင်းနိုင်သောကြောင့် cursor နှစ်ခု သီးခြားလိုသည်။ Response တွင် has_more ပါလျှင် browser က ခန့်မှန်း 100 millisecond ကြားဖြင့် backlog ကို ဆက်ယူသည်။')
tech.pair('Live controls choose sensor, detection severity and a 5-minute, 15-minute or one-hour feed window. Severity filters detections, not raw events. The API allows a time window of at most 24 hours and a response limit of 10–200 items, normally 100. Browser retention is 100 event rows and 60 detection cards. Changed cards are replaced by session ID; cards no longer matching severity are removed. Apply resets the snapshot; a request-generation guard prevents older in-flight responses from overwriting newly selected filters.', 'Live control တွင် sensor၊ detection severity နှင့် 5 မိနစ်၊ 15 မိနစ် သို့မဟုတ် တစ်နာရီ feed window ကို ရွေးနိုင်သည်။ Severity filter သည် detection ကိုသာ စစ်ပြီး raw event ကိုမစစ်ပါ။ API က အများဆုံး 24 နာရီ window နှင့် request တစ်ခုလျှင် item 10–200၊ ပုံမှန် 100 ကို ခွင့်ပြုသည်။ Browser တွင် event row 100 နှင့် detection card 60 ကို ထိန်းထားသည်။ ပြောင်းသော card ကို session ID ဖြင့် အစားထိုးပြီး severity မကိုက်တော့လျှင် ဖယ်သည်။ Apply က snapshot ပြန်စပြီး request generation စစ်ခြင်းက အဟောင်း response ကို filter အသစ်ပေါ် ပြန်မရေးစေပါ။')
tech.pair('The counters always summarize five minutes; choosing a longer feed window does not change them. The line chart covers fifteen minutes across all sensors. Heartbeats are written every three seconds; online requires an online status and a heartbeat younger than fifteen seconds. Stale sensors show zero active connections, and the connection list hides stale sensor rows. /health only shows that the web endpoint responds; it does not prove SSH is listening or analysis is healthy. Pause freezes the live view, not collection. Overview refresh and some cached APIs have their own slower intervals.', 'Counter များသည် အမြဲငါးမိနစ်စာဖြစ်ပြီး feed window ပိုရှည်ရွေးလျှင် မလိုက်ပြောင်းပါ။ Line chart သည် sensor အားလုံး၏ 15 မိနစ်စာကို ပြသည်။ Heartbeat ကို သုံးစက္ကန့်တစ်ကြိမ်သိမ်းပြီး status online ဖြစ်ကာ heartbeat သက်တမ်း 15 စက္ကန့်မပြည့်မှ online ဟုယူသည်။ Heartbeat ဟောင်းသော sensor အတွက် active connection သုညပြပြီး စာရင်းမှလည်း ဖယ်သည်။ /health အောင်မြင်ခြင်းသည် web endpoint တုံ့ပြန်နေကြောင်းသာဖြစ်ပြီး SSH နားထောင်နေခြင်း သို့မဟုတ် analysis ကောင်းနေခြင်း၏ သက်သေမဟုတ်ပါ။ Pause သည် screen ကိုသာ ရပ်ပြီး collection မရပ်ပါ။ Overview နှင့် cached API အချို့တွင် သီးခြား ပိုနှေးသော refresh interval ရှိသည်။')

tech.chapter('13. Analyst login and incident workflow','Analyst login နှင့် incident စုံစမ်းစစ်ဆေးပုံ')
tech.pair('manage.py analyst creates or resets a local account, requires a password of at least twelve characters, stores a Werkzeug scrypt hash and changes an auth_version value. Every protected request checks that version against the database, so resetting the account invalidates its old sessions. Flask cookies are signed, HttpOnly and SameSite=Strict; Secure is enabled only when HONEYTRACE_HTTPS=true. The configured permanent-session lifetime is eight hours, normally refreshed by Flask requests, so it should not be advertised as a strict eight-hour absolute logout deadline.', 'manage.py analyst သည် local account ဖန်တီး သို့မဟုတ် reset လုပ်ပြီး အနည်းဆုံးစာလုံး 12 လုံး password လိုသည်။ Werkzeug scrypt hash သိမ်းကာ auth_version ပြောင်းသည်။ Protected request တိုင်း database နှင့် version စစ်သဖြင့် account reset လုပ်လျှင် session အဟောင်းများ ပျက်သွားသည်။ Flask cookie ကို sign လုပ်ထားပြီး HttpOnly နှင့် SameSite=Strict သတ်မှတ်ထားသည်။ HONEYTRACE_HTTPS=true ဖြစ်မှ Secure flag ပါသည်။ Permanent session lifetime ကို ရှစ်နာရီထားသော်လည်း Flask request များက ပုံမှန် refresh လုပ်နိုင်သဖြင့် login ဝင်ပြီး ရှစ်နာရီတိတိတွင် မဖြစ်မနေ logout ဖြစ်သည်ဟု မပြောသင့်ပါ။')
tech.pair('Anonymous API reads receive 401 and anonymous page requests redirect to login. POST, PATCH and DELETE require a CSRF token; invalid tokens receive 403. Login rate limiting is per source IP in this dashboard process, with five attempts in a five-minute window before blocking; restarting the process resets it. Security headers restrict script sources, framing and caching. These protections do not add TLS to the default HTTP listener, encrypt the database, or provide MFA, role-based privileges or tamper-proof audit storage.', 'Login မဝင်သော API read ကို 401 ပြန်ပြီး page request ကို login သို့ပို့သည်။ POST၊ PATCH နှင့် DELETE တွင် CSRF token လိုပြီး မမှန်လျှင် 403 ပြန်သည်။ Login rate limit သည် dashboard process ထဲရှိ source IP အလိုက်ဖြစ်ကာ ငါးမိနစ်အတွင်း ကြိုးစားမှုငါးကြိမ်နောက်တွင် ပိတ်သည်။ Process restart လုပ်လျှင် limiter reset ဖြစ်သည်။ Security header များက script source၊ frame နှင့် cache ကိုကန့်သတ်သည်။ သို့သော် default HTTP ကို TLS ဖြစ်အောင် မလုပ်ပေးသလို database encryption၊ MFA၊ role ခွဲခြားမှုနှင့် ပြင်ဆင်မရသော audit storage တို့ မပါပါ။')
tech.pair('sync_incidents creates an incident for a live session whose current severity is high or critical, or updates an existing incident for the same session key. Repeated activity updates one record instead of producing a separate incident per event. Analysts choose New, Investigating or Resolved and add notes. Status changes and notes record the analyst name and time. Later activity with a newer last_seen reopens a resolved incident in that same session as New; this automatic reopen is not separately appended to the note history by the current code.', 'sync_incidents သည် လက်ရှိ severity high သို့မဟုတ် critical ဖြစ်သော live session အတွက် incident ဖန်တီးသည် သို့မဟုတ် session key တူသော ရှိပြီးသား incident ကိုပြင်သည်။ Event တစ်ခုစီ incident အသစ်မထုတ်ဘဲ ထပ်လာသောလုပ်ဆောင်မှုကို record တစ်ခုတည်းတွင် ပြင်သည်။ Analyst သည် New၊ Investigating သို့မဟုတ် Resolved ရွေးပြီး note ရေးနိုင်သည်။ Status ပြောင်းခြင်းနှင့် note တွင် analyst အမည်နှင့် အချိန်ပါသည်။ Session တူအတွင်း last_seen ပိုသစ်သော activity ထပ်လာလျှင် resolved incident ကို New ပြန်ပြောင်းသည်။ လက်ရှိ code က ထိုအလိုအလျောက် reopen ကို note history ထဲ သီးခြားမရေးပါ။')
tech.pair('The queue displays the latest 200 matching incidents. A session detail shows at most the first 500 evidence events; CSV export includes incident metadata, up to 5,000 ordered events and analyst notes. Export login summaries are redacted and leading spreadsheet-formula characters are escaped. Complete source IPs are displayed by default for investigation; optional masking can be enabled for shared screens. Arbitrary secrets inside command strings are not comprehensively removed. Export is a useful reporting artifact, not a cryptographically signed forensic chain of custody.', 'Incident queue သည် filter ကိုက်သော နောက်ဆုံး record 200 ကို ပြသည်။ Session detail တွင် အချိန်အစီအစဉ်အရ ပထမ evidence event 500 အထိသာပြပြီး CSV တွင် incident metadata၊ event 5,000 အထိနှင့် analyst note ပါသည်။ Export login summary ကိုဖုံးပြီး spreadsheet formula အဖြစ် အဓိပ္ပာယ်ကောက်နိုင်သော ရှေ့စာလုံးများကို escape လုပ်သည်။ စုံစမ်းစစ်ဆေးရန် source IP အပြည့်အစုံကို ပုံမှန်ပြပြီး screen မျှဝေသည့်အခါ optional masking ဖွင့်နိုင်သည်။ Command string ထဲရှိ secret အားလုံးကို အပြည့်အဝမဖယ်နိုင်ပါ။ Export သည် report အတွက်အသုံးဝင်သော်လည်း cryptographic လက်မှတ်ပါသော forensic chain of custody မဟုတ်ပါ။')

tech.chapter('14. Database and API reference','Database နှင့် API အညွှန်း')
tech.table(['Table','Purpose / အသုံးဝင်ပုံ'],[(a,b) for a,b in [
('events','Normalized evidence and analysis_session_id link. / ပုံစံတူ event နှင့် session ချိတ်ဆက်မှု။'),('sessions','Burst summary, rule/model/final labels and severity. / Burst အနှစ်ချုပ်၊ rule/model/final label နှင့် severity။'),('session_features','One JSON feature object per session. / Session တစ်ခုလျှင် feature JSON တစ်ခု။'),('session_changes','Append-only insert/update revision feed; no implemented retention job. / Insert/update revision စာရင်း၊ retention job မရှိသေး။'),('imports','File identity, provenance, progress, counts and errors. / File identity၊ မူရင်း၊ progress၊ count နှင့် error။'),('model_runs','Version, metrics, classes, importance and evaluation metadata. / Model version၊ metric၊ class၊ importance နှင့် evaluation အချက်အလက်။'),('sensors','Latest heartbeat, status, backlog, timing and drop counter. / နောက်ဆုံး heartbeat၊ status၊ backlog၊ timing နှင့် drop counter။'),('active_connections','Persisted native connections linked to a sensor. / Sensor နှင့်ချိတ်ထားသော active native connection။'),('analysts','Username, password hash, authentication version. / Username၊ password hash နှင့် auth version။'),('incidents','One investigation record per session key. / Session key တစ်ခုလျှင် investigation record တစ်ခု။'),('incident_notes','Analyst-authored notes and manual status changes. / Analyst note နှင့် လူကပြောင်းသော status မှတ်တမ်း။')]], [2900,6600])
tech.pair('SQLite connections enable foreign keys, WAL journaling, NORMAL synchronous mode and a busy timeout. Indexes support event time, source/IP/time, session linkage and common filters. ManagedConnection commits or rolls back, then closes on context exit. WAL helps readers coexist with a writer; it does not turn SQLite into a distributed multi-writer database. Some logical links, including incident session IDs, are not foreign-key constrained. Retention, archival rotation and distributed ingestion are not implemented.', 'SQLite connection များတွင် foreign key၊ WAL journaling၊ NORMAL synchronous mode နှင့် busy timeout ဖွင့်ထားသည်။ Index များက event time၊ source/IP/time၊ session link နှင့် filter များကို ကူညီသည်။ ManagedConnection သည် context ထွက်ရာတွင် commit သို့မဟုတ် rollback လုပ်ပြီး close လုပ်သည်။ WAL က reader နှင့် writer တစ်ပြိုင်နက်အလုပ်လုပ်ရန် ကူညီသော်လည်း SQLite ကို distributed multi-writer database အဖြစ် မပြောင်းပေးပါ။ Incident session ID အပါအဝင် logical link အချို့သည် foreign key ဖြင့်မကန့်သတ်ထားပါ။ Retention၊ archival rotation နှင့် distributed ingestion မပါသေးပါ။')
tech.table(['Route','Use and limits / အသုံးနှင့် ကန့်သတ်ချက်'],[
('GET /health','Public web-process response only. / Public web တုံ့ပြန်မှုစစ်ရန်သာ။'),('GET/POST /login; POST /logout','Analyst access; write requests require CSRF. / Analyst ဝင်ထွက်ခြင်း၊ write တွင် CSRF လို။'),('GET /api/live','Snapshot or incremental feed, health, active connections, chart data. / Snapshot သို့မဟုတ် ပြောင်းလဲမှု feed နှင့် health data။'),('GET /api/overview; /api/timeline','Historical totals and daily session timeline. / Historical စုစုပေါင်းနှင့် နေ့အလိုက် session timeline။'),('GET /api/sessions','Paged filters; per_page 10–200, default 50. / Page ခွဲ filter၊ တစ်မျက်နှာ 10–200၊ ပုံမှန် 50။'),('GET /api/sessions/<id>','Summary, features, up to 500 events. / အနှစ်ချုပ်၊ feature နှင့် event 500 အထိ။'),('GET /api/model; /api/sources; /api/imports','Saved evaluation, source comparison, latest 200 imports. / Evaluation၊ source နှိုင်းယှဉ်မှု၊ import 200 အထိ။'),('GET /api/incidents','Status/severity filters; latest 200. / Status/severity filter၊ နောက်ဆုံး 200။'),('GET/PATCH /api/incidents/<id>','Read or save status/note; note maximum 4,000 characters. / Status/note ဖတ်ရေး၊ note စာလုံး 4,000 အထိ။'),('GET /api/incidents/<id>/export.csv','Authenticated evidence download, up to 5,000 events. / Login လိုအပ်သော evidence download၊ event 5,000 အထိ။')],[3800,5700])

tech.chapter('15. Cowrie data, independence and fair comparison','Cowrie data၊ ကိုယ်ပိုင်စနစ်ဖြစ်မှုနှင့် မျှတသောနှိုင်းယှဉ်မှု')
tech.pair('The live runtime does not require a Cowrie service. The optional importer reads authorized Cowrie JSON files, directories or ZIP members as historical training/comparison data. It streams lines, records provenance, commits in batches of 2,000, counts invalid and duplicate records, marks limited runs partial, and skips file identities already marked complete. Importing historical records is not the same as receiving a live network connection. Historical imports do not automatically create the live incident queue.', 'Live runtime အတွက် Cowrie service မလိုပါ။ Optional importer သည် ခွင့်ပြုထားသော Cowrie JSON file၊ directory သို့မဟုတ် ZIP member များကို historical training/comparison data အဖြစ်ဖတ်သည်။ Line အလိုက်ဖတ်၊ မူရင်းအချက်အလက်သိမ်း၊ event 2,000 စီ commit လုပ်၊ invalid နှင့် duplicate ရေတွက်၊ ကန့်သတ် run ကို partial သတ်မှတ်ပြီး complete ဖြစ်သော file identity ကို ကျော်သည်။ Historical record import လုပ်ခြင်းသည် live network connection လက်ခံခြင်းနှင့် မတူပါ။ Historical import များက live incident queue ကို အလိုအလျောက် မဖန်တီးပါ။')
tech.pair('A defensible comparison separates sensor realism from analytics and workflow. Compare the documented Cowrie baseline and HoneyTrace under the same authorized scenarios, hardware, observation duration and label-review procedure. Measure event completeness, classification errors, event-to-display latency, resource use and analyst steps. Do not assume Cowrie is merely a basic log collector or claim HoneyTrace outperforms it without a controlled comparison. This document verifies HoneyTrace code only; it is not a current Cowrie product capability audit.', 'မျှတသောနှိုင်းယှဉ်မှုတွင် sensor ၏ အစစ်နှင့်ဆင်တူမှုကို analytics နှင့် workflow မှ ခွဲစဉ်းစားရမည်။ မှတ်တမ်းပြုထားသော Cowrie baseline နှင့် HoneyTrace ကို ခွင့်ပြုထားသော scenario တူ၊ hardware တူ၊ လေ့လာချိန်တူ၊ label ပြန်စစ်နည်းတူဖြင့် နှိုင်းယှဉ်ပါ။ Event ပြည့်စုံမှု၊ classification အမှား၊ event-to-display ကြာချိန်၊ resource အသုံးနှင့် analyst အဆင့်အရေအတွက်တို့ကို တိုင်းပါ။ Cowrie ကို log collector သာဟု မယူဆသင့်သလို controlled comparison မရှိဘဲ HoneyTrace ပိုကောင်းသည်ဟု မဆိုသင့်ပါ။ ဤစာတမ်းသည် HoneyTrace code ကိုသာ စစ်ထားခြင်းဖြစ်ပြီး လက်ရှိ Cowrie product capability audit မဟုတ်ပါ။')

tech.chapter('16. Installation, daily startup and configuration','တပ်ဆင်ခြင်း၊ နေ့စဉ်ဖွင့်ခြင်းနှင့် configuration')
tech.pair('On this computer, stop older instances first, then run the following in PowerShell. The bundled .python interpreter is local to this checkout and is not included in GitHub. A new computer needs Python 3.12+ and an isolated environment; this implementation was tested with Python 3.14. Choose your own analyst password when prompted. Do not paste real SSH decoy credentials into a presentation.', 'ဤကွန်ပျူတာတွင် အဟောင်း service များကို အရင်ရပ်ပြီး PowerShell တွင် အောက်ပါအတိုင်းလုပ်ပါ။ .python interpreter သည် ဤ local checkout တွင်သာရှိပြီး GitHub ထဲမပါပါ။ ကွန်ပျူတာအသစ်တွင် Python 3.12 နှင့်အထက်၊ သီးခြား environment လိုသည်။ ဤ implementation ကို Python 3.14 ဖြင့် စမ်းထားသည်။ မေးလာသောအခါ မိမိ analyst password ကို ရွေးထည့်ပါ။ အသုံးပြုနေသော SSH decoy credential ကို presentation ထဲတွင် မဖော်ပြပါနှင့်။')
tech.code('cd C:\\School\\NISec\n.\\.python\\python.exe -m pip install -r requirements.txt\n.\\.python\\python.exe manage.py init\n.\\.python\\python.exe manage.py analyst --username admin')
tech.section('Daily operation: two terminals','နေ့စဉ်အသုံးပြုရန် terminal နှစ်ခု')
tech.code('# Terminal 1\ncd C:\\School\\NISec\n.\\.python\\python.exe manage.py honeypot\n\n# Terminal 2\ncd C:\\School\\NISec\n.\\.python\\python.exe manage.py dashboard')
tech.pair('Open http://127.0.0.1:5000 and sign in. Keep both service terminals open. Verify sensor heartbeat, not just the page loading. Closing the browser is harmless to collection; Ctrl+C in the sensor terminal stops collection, and Ctrl+C in the dashboard terminal stops web access. Reopening does not require retraining because the model is loaded from disk. If the artifact is absent, live classification falls back to rules; a corrupt or incompatible artifact is an error, not the same as an absent artifact.', 'http://127.0.0.1:5000 ကိုဖွင့်ပြီး login ဝင်ပါ။ Service terminal နှစ်ခုလုံးကို ဖွင့်ထားပါ။ Page ပေါ်ရုံမဟုတ်ဘဲ sensor heartbeat ကို စစ်ပါ။ Browser ပိတ်ခြင်းက collection ကိုမထိခိုက်ပါ။ Sensor terminal တွင် Ctrl+C လုပ်လျှင် collection ရပ်ပြီး dashboard terminal တွင် Ctrl+C လုပ်လျှင် web access ရပ်သည်။ Model ကို disk မှဖတ်သဖြင့် ပြန်ဖွင့်တိုင်း training မလိုပါ။ Artifact မရှိလျှင် live classification သည် rule ဖြင့်ဆက်လုပ်သည်။ ပျက်နေသော သို့မဟုတ် version မကိုက်သော artifact သည် မရှိခြင်းနှင့်မတူဘဲ error ဖြစ်သည်။')
tech.table(['Setting','Default and meaning / ပုံမှန်တန်ဖိုးနှင့် အဓိပ္ပာယ်'],[
('NISEC_INSTANCE_DIR / NISEC_DB_PATH','instance / instance/nisec.db; sensor and dashboard must agree. / Sensor နှင့် dashboard တူညီသော path သုံးရမည်။'),('NISEC_MODEL_DIR / NISEC_MODEL_PATH','model / model/behavior_model.joblib; trusted local artifact only. / ယုံကြည်ရသော local model ကိုသာသုံး။'),('NISEC_SECRET_KEY_PATH','instance/credential.key; keep with backups. / Backup နှင့်အတူ ထိန်းထားရန်။'),('NISEC_SESSION_GAP_SECONDS','120; changing it changes grouping semantics. / 120၊ ပြောင်းလျှင် grouping အဓိပ္ပာယ်ပြောင်း။'),('NISEC_MASK_IPS','false by default; set true for UI/export masking. Storage still keeps the source IP. / ပုံမှန် false၊ UI/export တွင်ဖုံးရန် true ထား။ Storage တွင် IP အစစ်ရှိနေသည်။'),('HONEYTRACE_DECOY_PASSWORD','Controls decoy SSH authentication only. / Decoy SSH login အတွက်သာ။'),('HONEYTRACE_HTTPS','false by default; true enables Secure cookies behind actual HTTPS. / ပုံမှန် false၊ HTTPS အမှန်ရှိမှ true ထား။'),('--host / --port','Sensor defaults 127.0.0.1:2222; dashboard 127.0.0.1:5000. / ပုံမှန် localhost ပေါ်တွင်သာ နားထောင်သည်။')],[3900,5600])
tech.note('127.0.0.1 means this computer only. A second lab computer requires an authorized private/host-only route to a deliberately chosen sensor interface. Do not expose the dashboard publicly. This guide does not change firewall rules or provide traffic-generation instructions.','127.0.0.1 သည် ဤကွန်ပျူတာတစ်လုံးတည်းကို ဆိုလိုသည်။ အခြား lab computer မှသုံးလိုလျှင် ရည်ရွယ်ရွေးထားသော sensor interface သို့ ခွင့်ပြုထားသည့် private/host-only route လိုသည်။ Dashboard ကို public မဖွင့်ပါနှင့်။ ဤလမ်းညွှန်သည် firewall မပြောင်းပေးသလို traffic ထုတ်လုပ်ရန် နည်းလမ်းမပေးပါ။')

tech.chapter('17. Troubleshooting and verification','ပြဿနာရှာဖွေခြင်းနှင့် စစ်ဆေးအတည်ပြုခြင်း')
tech.table(['Symptom','Interpretation and operator action / အဓိပ္ပာယ်နှင့် ဖြေရှင်းရန်'],[
('Dashboard loads; sensor offline','Start/check the SSH process, bind errors, heartbeat age and shared DB configuration. / SSH process၊ bind error၊ heartbeat သက်တမ်းနှင့် DB path တူမှုစစ်။'),('No recent events','An online idle sensor can legitimately have no traffic. Check time window and source filters. / Online ဖြစ်သော်လည်း traffic မရှိနိုင်၊ time window နှင့် source filter စစ်။'),('Detection appears later than event','Worker grouping/model processing is asynchronous. Inspect queue and processing time. / Worker/model အလုပ် သီးခြားဖြစ်၍ နောက်ကျနိုင်၊ queue နှင့် processing time စစ်။'),('401 / 403','Sign in again; reload for a fresh CSRF token. / ပြန် login ဝင်၊ CSRF token အသစ်အတွက် reload လုပ်။'),('429 on login','Wait five minutes; do not keep retrying because repeated blocked attempts extend the rolling window. / ငါးမိနစ်စောင့်၊ အဆက်မပြတ်ကြိုးစားလျှင် window ရှည်နိုင်။'),('Model error','Check the trusted artifact and matching dependencies; inspect sensor logs. Do not load an untrusted replacement. / ယုံကြည်ရသော artifact၊ dependency ကိုက်မှုနှင့် log စစ်၊ မသိသော model မထည့်။'),('Port already in use','Stop only the known older project process or choose a documented free port. / သိထားသော project process အဟောင်းကိုသာရပ် သို့မဟုတ် port ပြောင်း။'),('Old incident evidence missing after rebuild','Full rebuild changed session IDs; preserve metadata and restore/repair from a consistent backup if needed. / Full rebuild ကြောင့် ID ပြောင်းနိုင်၊ metadata ထိန်းပြီး လိုလျှင် consistent backup မှပြန်ယူ။'),('Data missing after crash','Queued but uncommitted events may be lost; stopped-service backups and future durable ingestion are needed. / Queue ထဲမသိမ်းရသေးသော data ပျောက်နိုင်၊ service ရပ်ထားသော backup နှင့် durable ingestion လို။')],[3200,6300])
tech.code('.\\.python\\python.exe -m unittest discover -s tests -v\nnode --check static/dashboard.js\nnode --check static/operations.js\n.\\.python\\python.exe -m pip check')
tech.pair('The committed test suite contains six core unit tests and a wrapper which runs five isolated integration tests. Coverage includes labeling examples, credential handling, feature extraction, actual localhost SSH negotiation, virtual commands including interactive line endings, denied forwarding/SFTP, stable live session IDs, revision visibility, authentication and CSRF, stale heartbeat behavior, incident edits and CSV escaping. Tests use temporary storage and an ephemeral SSH port. Passing them does not establish production throughput, complete protocol correctness or real-world ML accuracy.', 'Commit ထဲရှိ test suite တွင် core unit test ခြောက်ခုနှင့် isolated integration test ငါးခုကိုခေါ်သော wrapper တစ်ခုပါသည်။ Label ဥပမာများ၊ credential handling၊ feature extraction၊ localhost SSH အမှန်တကယ်ချိတ်ဆက်မှု၊ interactive line ending ပါသော virtual command၊ forwarding/SFTP ငြင်းပယ်မှု၊ stable ID၊ revision၊ login/CSRF၊ heartbeat ဟောင်းမှု၊ incident ပြင်ခြင်းနှင့် CSV escape တို့ကို စစ်သည်။ Temporary storage နှင့် အလွတ် SSH port ကိုသုံးသည်။ Test အောင်မြင်ခြင်းက production throughput၊ protocol အပြည့်အစုံမှန်ကန်မှု သို့မဟုတ် real-world ML accuracy ကို မသက်သေပြပါ။')

tech.chapter('18. File-by-file maintenance map','File တစ်ခုချင်း၏ တာဝန်နှင့် ပြင်ဆင်ရန်နေရာ')
tech.table(['File','Responsibility / တာဝန်'],[
('manage.py','Startup, import, session build, training and analyst CLI. / စတင်ခြင်း၊ import၊ session၊ training နှင့် account CLI။'),('config.py','Paths, environment settings and default limits. / Path၊ environment နှင့် default limit။'),('ssh_honeypot.py','SSH callbacks, queue, worker, heartbeat and shutdown. / SSH callback၊ queue၊ worker၊ heartbeat နှင့်ပိတ်ခြင်း။'),('virtual_shell.py','Simulated filesystem and command responses only. / အတု filesystem နှင့် command အဖြေများ။'),('ingest.py / privacy.py','Normalization, dedup identity and credential-safe transforms. / ပုံစံပြောင်း၊ duplicate identity နှင့် credential ဖုံးခြင်း။'),('sessionizer.py','Time-gap grouping, feature persistence and stable live upsert. / အချိန်ကွာခြားမှု grouping၊ feature သိမ်းနှင့် live upsert။'),('feature_engineering.py','Exact feature order and numeric calculations. / Feature အစီအစဉ်နှင့် ကိန်းဂဏန်းတွက်ချက်မှု။'),('labeling.py','Rule precedence, thresholds and severity mapping. / Rule အစီအစဉ်၊ threshold နှင့် severity။'),('model_service.py','Grouped training, model selection, artifact and inference. / Grouped training၊ model ရွေး၊ သိမ်းနှင့် prediction။'),('db.py','Additive schema, indexes, triggers and connections. / Schema၊ index၊ trigger နှင့် connection။'),('operations.py','Login security, health data and incident API. / Login security၊ health data နှင့် incident API။'),('live_api.py','Independent event/revision cursors and bounded filtering. / Event/revision cursor နှင့် ကန့်သတ် filter။'),('app.py','Dashboard routing and historical read APIs. / Dashboard route နှင့် historical API။'),('templates/dashboard.html / login.html','Page structure, fields and navigation. / Page ဖွဲ့စည်းပုံ၊ field နှင့် navigation။'),('static/style.css','Colors, spacing, responsive layout and focus states. / အရောင်၊ အကွာအဝေး၊ responsive layout နှင့် focus။'),('static/dashboard.js / operations.js','Data requests, rendering, live controls, chart and incident editing. / Data တောင်း၊ ပြသ၊ live control၊ chart နှင့် incident ပြင်ခြင်း။'),('static/vendor/','Locally served Chart.js and its license. / Local Chart.js နှင့် license။'),('import_cowrie.py','Optional historical data import and provenance. / Optional historical import နှင့် မူရင်းမှတ်တမ်း။'),('tests/','Unit/integration tests and temporary preview fixture. / Unit/integration test နှင့် temporary preview။'),('README.md / SECURITY.md / docs/OPERATIONS.md','Project introduction, security boundaries and run guide. / Project မိတ်ဆက်၊ security နယ်နိမိတ်နှင့် run guide။')],[3900,5600])
tech.pair('A visual-only dashboard change normally belongs in HTML/CSS/JavaScript and requires a dashboard restart when templates/backend change plus a browser hard refresh. It does not require retraining. Feature definitions, feature order, label rules or training-data changes require deliberate reevaluation and may require retraining. Keep code/version, feature schema and model artifact compatible. Never commit instance data, model files, credentials or environment secrets merely to make the demo easier to start.', 'Dashboard အလှအပပြောင်းလဲမှုသည် ပုံမှန်အားဖြင့် HTML/CSS/JavaScript တွင် ပြင်ရပြီး template/backend ပြောင်းလျှင် dashboard restart နှင့် browser hard refresh လုပ်ရသည်။ Training ပြန်လုပ်ရန် မလိုပါ။ Feature definition၊ feature အစီအစဉ်၊ label rule သို့မဟုတ် training data ပြောင်းလျှင် ရည်ရွယ်ချက်ရှိရှိ ပြန်စစ်ရပြီး retraining လိုနိုင်သည်။ Code version၊ feature schema နှင့် model artifact ကို ကိုက်ညီအောင်ထားပါ။ Demo လွယ်ကူစေရန်ဟုဆိုပြီး instance data၊ model၊ credential နှင့် environment secret များကို GitHub သို့မတင်ပါနှင့်။')

tech.chapter('19. Current limitations and next engineering priorities','လက်ရှိကန့်သတ်ချက်များနှင့် နောက်တစ်ဆင့် ဦးစားပေးရန်')
tech.pair('Implemented now: actual SSH transport; a bounded decoy terminal; ongoing event collection and classification; persistent local evidence; change-aware live monitoring; analyst authentication; grouped incidents, notes and CSV. Not implemented: a full Linux system, arbitrary malware execution, a web honeypot target, network-wide scanning, automatic blocking, multi-sensor remote collectors, SIEM export integrations, MFA/RBAC, email alerts, durable queues, automated retention or high-availability failover.', 'လက်ရှိပါဝင်သည်မှာ SSH transport အစစ်၊ ကန့်သတ်ထားသော decoy terminal၊ အဆက်မပြတ် event collection/classification၊ local evidence သိမ်းခြင်း၊ ပြောင်းလဲမှုသိသော live monitor၊ analyst login၊ grouped incident၊ note နှင့် CSV တို့ဖြစ်သည်။ Linux system အပြည့်၊ malware အမှန်တကယ် run ခြင်း၊ web honeypot target၊ network တစ်ခုလုံး scan ခြင်း၊ အလိုအလျောက် block ခြင်း၊ remote collector များ၊ SIEM integration၊ MFA/RBAC၊ email alert၊ durable queue၊ automatic retention နှင့် failover တို့ မပါပါ။')
tech.pair('Priorities before wider deployment: (1) independent labels and live-domain validation; (2) safer rule/model fusion, explicit unsupported-class handling and explanation consistency; (3) durable telemetry and retention; (4) immutable or integrity-checked audit records and stable incident evidence across rebuilds; (5) measured throughput/latency and supervised restarts; (6) HTTPS, least-privilege process isolation, backups and management-network restrictions. These are future work, not completed features.', 'ပိုကျယ်ပြန့်စွာအသုံးမပြုမီ ဦးစားပေးရန်မှာ (1) လွတ်လပ်စွာအတည်ပြုထားသော label နှင့် live-domain စစ်ခြင်း၊ (2) rule/model ပေါင်းစပ်ပုံ၊ unsupported class ကိုင်တွယ်ပုံနှင့် ရှင်းလင်းချက်ကိုက်ညီမှု၊ (3) durable telemetry နှင့် retention၊ (4) audit integrity နှင့် rebuild လုပ်လျှင်လည်း incident evidence link မှန်နေခြင်း၊ (5) throughput/latency တိုင်းခြင်းနှင့် process supervision၊ (6) HTTPS၊ အခွင့်အရေးအနည်းဆုံးပေးထားသော isolation၊ backup နှင့် management network ကန့်သတ်ခြင်းတို့ဖြစ်သည်။ ဤအချက်များသည် နောက်လုပ်ရန်ဖြစ်ပြီး ပြီးစီးပြီးသား feature မဟုတ်ပါ။')
tech.pair('Source basis: this guide was checked against the local source files listed in Chapter 18 at commit 4d97809, plus the repository README and operator/security notes. Where a README claim is broader than the current implementation, this guide states the narrower code behavior. No new benchmark or production certification was performed to write this document.', 'ဤစာတမ်းကို commit 4d97809 ရှိ အခန်း 18 တွင်ဖော်ပြသော source file များ၊ README နှင့် operator/security note များအပေါ် အခြေခံစစ်ဆေးထားသည်။ README စကားလုံးက code ထက် ပိုကျယ်သွားသောနေရာတွင် ဤစာတမ်းက code ၏ ပိုကန့်သတ်ထားသော လုပ်ဆောင်ချက်အတိုင်း ရှင်းပြထားသည်။ ဤစာတမ်းရေးရန် benchmark အသစ် သို့မဟုတ် production certification မလုပ်ထားပါ။')

present = Guide('Explaining HoneyTrace', 'Teacher presentation, viva and basic-IT audience guide / တင်ပြခြင်းနှင့် မေးခွန်းဖြေဆိုရန် လမ်းညွှန်', 'HoneyTrace_Presentation_Guide_EN_MY.docx')
present.chapter('1. How to use this presentation guide','ဤတင်ပြလမ်းညွှန်ကို အသုံးပြုပုံ')
present.pair('This document gives two levels of explanation: an academic defense for your teacher and a plain-language explanation for someone who knows basic IT but not cybersecurity. English and Burmese versions are paired. Select one speaking language for a presentation; do not read both versions aloud unless translation is requested. Suggested timings are rehearsal targets, not measured speaking durations.', 'ဤစာတမ်းတွင် ဆရာအတွက် နည်းပညာနှင့် သုတေသနအကြောင်းပြချက်ပါသော ရှင်းလင်းချက်တစ်မျိုး၊ အခြေခံ IT သိသော်လည်း cybersecurity မသိသူအတွက် ရိုးရှင်းသော ရှင်းလင်းချက်တစ်မျိုး ပါဝင်သည်။ English နှင့် မြန်မာကို တွဲထားသည်။ Presentation တစ်ခုအတွက် ပြောမည့်ဘာသာစကားတစ်မျိုးကို ရွေးပါ။ ဘာသာပြန်တောင်းမှသာ နှစ်မျိုးစလုံးဖတ်ပါ။ အချိန်သတ်မှတ်ချက်များသည် လေ့ကျင့်ရန်အတွက် ခန့်မှန်းချက်ဖြစ်ပြီး အမှန်တကယ်တိုင်းထားသော ပြောချိန်မဟုတ်ပါ။')
present.pair('Use “the project implements” for verified behavior, “the recorded evaluation reports” for existing metrics, and “I would add” for future work. Adapt first-person scripts so they honestly reflect your own contribution and your school’s rules on libraries and AI assistance. Do not claim to have personally written every line, manually labeled the dataset, or independently verified every attack if you did not.', 'အတည်ပြုထားသောလုပ်ဆောင်ချက်ကို project က လုပ်ဆောင်ထားသည်ဟု ပြောပါ။ ရှိပြီးသား metric ကို မှတ်တမ်းတင်ထားသော evaluation တွင် ဖော်ပြထားသည်ဟု ပြောပါ။ နောက်လုပ်မည့်အရာကို နောင်တွင်ထည့်မည်ဟု ပြောပါ။ ပထမပုဂ္ဂိုလ်သုံး script များကို မိမိအမှန်တကယ်ပါဝင်မှုနှင့် ကျောင်း၏ library/AI assistance စည်းမျဉ်းအတိုင်း ပြင်သုံးပါ။ ကိုယ်မရေးခဲ့သော code အားလုံးကို ကိုယ်တိုင်ရေးသည်၊ data အားလုံးကို လူက label ပေးသည်၊ တိုက်ခိုက်မှုအားလုံးကို လွတ်လပ်စွာအတည်ပြုသည်ဟု မပြောပါနှင့်။')
present.note('Your strongest claim is traceability: an observed event leads to a grouped session, a documented classification and an analyst investigation. A smaller, explainable working system is more defensible than unsupported “industry-grade” claims.','အခိုင်မာဆုံးတင်ပြနိုင်သောအချက်မှာ traceability ဖြစ်သည်။ ဖြစ်ရပ်တစ်ခုမှ session၊ ရှင်းပြနိုင်သော classification နှင့် analyst investigation သို့ ဆက်စပ်ပြနိုင်သည်။ အထောက်အထားမရှိသော industry-grade ဆိုသည့်အဆိုထက် အရွယ်အစားသေးသော်လည်း အလုပ်လုပ်ပြီး ရှင်းပြနိုင်သောစနစ်ကို ကာကွယ်တင်ပြရ ပိုလွယ်သည်။')

present.chapter('2. One sentence, one minute and three minutes','တစ်ကြောင်း၊ တစ်မိနစ်နှင့် သုံးမိနစ်အတွင်း ရှင်းပြရန်')
present.section('One-sentence explanation','တစ်ကြောင်းတည်းဖြင့် ရှင်းပြချက်')
present.pair('HoneyTrace is a decoy SSH server that records interactions, groups suspicious behavior and helps an analyst investigate it through a live dashboard.', 'HoneyTrace သည် ဝင်ရောက်ဆက်သွယ်မှုများကို မှတ်တမ်းတင်၊ သံသယဖြစ်ဖွယ်အပြုအမူကို အုပ်စုဖွဲ့ပြီး live dashboard မှတစ်ဆင့် စုံစမ်းစစ်ဆေးနိုင်ရန် ကူညီပေးသော အတု SSH server ဖြစ်သည်။')
present.section('About one minute: general introduction','တစ်မိနစ်ခန့် မိတ်ဆက်စကား')
present.pair('HoneyTrace is a small deception and monitoring system. Instead of placing real business files behind a login, it offers a decoy remote-login service. Connections are real, but the terminal answers come from a controlled simulation, not from the host operating system. The system records what was submitted, groups related activity and uses documented rules plus a saved machine-learning model to suggest behavior categories. An analyst can watch recent activity, check whether the sensor is actually online, open an incident, write a note and export evidence. The current version works in an isolated lab; it is not a replacement for a firewall or a claim of perfect attack detection.', 'HoneyTrace သည် လှည့်စားမှုအခြေခံ စောင့်ကြည့်စနစ်ငယ်တစ်ခုဖြစ်သည်။ Login နောက်တွင် လုပ်ငန်းဖိုင်အစစ်များထားမည့်အစား အတု remote-login service တစ်ခုထားသည်။ Connection သည် အစစ်ဖြစ်သော်လည်း terminal အဖြေများသည် host operating system မှမဟုတ်ဘဲ ထိန်းချုပ်ထားသော simulation မှဖြစ်သည်။ စနစ်က ပေးပို့သည့်လုပ်ဆောင်ချက်များကို မှတ်တမ်းတင်၊ ဆက်စပ်မှုအလိုက် အုပ်စုဖွဲ့ပြီး rule နှင့် သိမ်းထားသော machine-learning model ဖြင့် အပြုအမူအမျိုးအစားကို အကြံပြုသည်။ Analyst သည် လတ်တလောဖြစ်ရပ်၊ sensor အမှန်တကယ် online ဖြစ်မှု၊ incident၊ note နှင့် evidence export ကို အသုံးပြုနိုင်သည်။ လက်ရှိ version သည် သီးခြား lab တွင် အသုံးပြုရန်ဖြစ်ပြီး firewall ကို အစားထိုးခြင်း သို့မဟုတ် attack အားလုံးဖမ်းနိုင်သည်ဟု ဆိုခြင်း မဟုတ်ပါ။')
present.section('About three minutes: teacher overview','ဆရာအတွက် သုံးမိနစ်ခန့် အနှစ်ချုပ်')
present.pair('The problem I am addressing is the gap between raw honeypot telemetry and evidence an analyst can use. A long list of login events is difficult to interpret on its own. HoneyTrace connects collection, grouping, classification and investigation in one workflow.\n\nThe live sensor is self-built at the application level. AsyncSSH provides the encrypted SSH protocol, while the project defines decoy authentication and an in-memory virtual terminal. It does not need a running Cowrie service. Cowrie logs are an optional historical data source for training and comparison.\n\nEvents are stored in SQLite and grouped by sensor, source address and inactivity gap. Thirty-one numerical features describe login volume, diversity, timing and command indicators. Rules create auditable labels; the saved model adds a statistical prediction. Separate event and session-revision cursors let the dashboard update a detection after new behavior or scoring arrives. High-risk sessions become incidents with notes and status tracking.\n\nThe evaluation is deliberately qualified: the recorded high scores measure agreement with rule-generated labels on grouped holdout data. They are not independently verified real-world detection rates. My demonstration will focus on evidence continuity, sensor health and the investigation workflow. Future work includes independent labels, durable ingestion, stronger model-rule fusion and deployment hardening.', 'ဖြေရှင်းလိုသောပြဿနာမှာ honeypot မှ raw telemetry နှင့် analyst တကယ်အသုံးချနိုင်သော evidence ကြားရှိ ကွာဟချက်ဖြစ်သည်။ Login event အရှည်ကြီးကိုသာကြည့်လျှင် နားလည်ရန်ခက်သည်။ HoneyTrace သည် collection၊ grouping၊ classification နှင့် investigation ကို workflow တစ်ခုတည်းတွင် ချိတ်ထားသည်။\n\nLive sensor ၏ application behavior ကို ကိုယ်ပိုင်ရေးထားသည်။ AsyncSSH က encrypted SSH protocol ကိုပေးပြီး project က decoy authentication နှင့် memory ထဲရှိ virtual terminal ကို သတ်မှတ်သည်။ Run နေသော Cowrie service မလိုပါ။ Cowrie log များကို training နှင့် comparison အတွက် optional historical data အဖြစ်သာ သုံးနိုင်သည်။\n\nEvent ကို SQLite တွင်သိမ်းပြီး sensor၊ source address နှင့် inactivity gap အလိုက် အုပ်စုဖွဲ့သည်။ Feature 31 ခုဖြင့် login ပမာဏ၊ မတူညီမှု၊ အချိန်နှင့် command indicator ကို ဖော်ပြသည်။ Rule က စစ်ဆေးရှင်းပြနိုင်သော label ထုတ်ပြီး saved model က ကိန်းဂဏန်းအခြေခံ prediction ထပ်ပေးသည်။ Event နှင့် session revision cursor သီးခြားထားသဖြင့် behavior သို့မဟုတ် score ပြောင်းသောအခါ detection ကို dashboard တွင် ပြန်ပြင်နိုင်သည်။ အန္တရာယ်မြင့် session များကို note နှင့် status ပါသော incident အဖြစ်ပြောင်းသည်။\n\nEvaluation ကို ကန့်သတ်ချက်နှင့်တကွ ပြောပါမည်။ မှတ်တမ်းတင်ထားသော score မြင့်များသည် grouped holdout data ပေါ်ရှိ rule-generated label နှင့် ကိုက်ညီမှုဖြစ်ပြီး လွတ်လပ်စွာစစ်ထားသော real-world detection rate မဟုတ်ပါ။ Demo တွင် evidence ဆက်စပ်မှု၊ sensor health နှင့် investigation workflow ကို အဓိကပြမည်။ နောက်တစ်ဆင့်တွင် independent label၊ durable ingestion၊ rule/model ပေါင်းစပ်ပုံနှင့် deployment security ကို ပိုကောင်းအောင်လုပ်ရန်ရှိသည်။')

present.chapter('3. Teacher presentation: 10–12 minute structure','ဆရာအတွက် 10–12 မိနစ် တင်ပြပုံ')
present.table(['Time / အချိန်','Focus / အဓိကအကြောင်း','Show / ပြရန်'],[
('0:00–1:00','Problem and project objective / ပြဿနာနှင့် ရည်ရွယ်ချက်','One-sentence objective / တစ်ကြောင်းအနှစ်ချုပ်'),('1:00–2:00','Scope and ownership / Scope နှင့် ကိုယ်ပိုင်ပါဝင်မှု','Self-built logic vs reused libraries / ကိုယ်ပိုင် logic နှင့် library'),('2:00–3:30','Architecture / ဖွဲ့စည်းပုံ','Sensor → queue → DB → analysis → dashboard'),('3:30–5:00','Behavior grouping and one rule / Grouping နှင့် rule တစ်ခု','Session ID, event count, rule reason / Session နှင့် evidence'),('5:00–6:30','ML and honest evaluation / ML နှင့် evaluation ကန့်သတ်ချက်','Grouped split, macro-F1, disclaimer / Group split နှင့် သတိပြုချက်'),('6:30–9:00','Operator demonstration / အသုံးပြုပုံပြ','Heartbeat → detection → incident → note → export'),('9:00–10:00','Safety and reliability / လုံခြုံမှုနှင့် reliability','Containment, authentication, backlog / ကန့်သတ်မှု၊ login၊ queue'),('10:00–12:00','Limits, future work, questions / ကန့်သတ်ချက်နှင့် မေးခွန်း','Three prioritized improvements / ဦးစားပေးတိုးတက်မှု သုံးခု')],[1500,4200,3800])
present.section('Opening and problem statement','အစပြုစကားနှင့် ပြဿနာသတ်မှတ်ချက်')
present.pair('“The objective is not just to display attack-looking charts. It is to make an observed interaction traceable from the sensor to an analyst decision. I chose an SSH decoy because it gives structured login and command behavior without needing a fake public website.”\n\nExplain the practical problem: hundreds of separate records may represent one behavioral burst. Grouping reduces fragmented evidence. Health monitoring distinguishes an idle sensor from a stopped one. Investigation notes preserve what the analyst concluded instead of losing it when the browser closes.', '“ရည်ရွယ်ချက်က attack ပုံစံ chart များပြရန်သာ မဟုတ်ပါ။ တွေ့ရှိသော interaction တစ်ခုကို sensor မှ analyst ဆုံးဖြတ်ချက်အထိ ဆက်စပ်စစ်ဆေးနိုင်စေရန်ဖြစ်သည်။ အတု public website မလိုဘဲ login နှင့် command behavior ရနိုင်သောကြောင့် SSH decoy ကို ရွေးထားသည်။”\n\nလက်တွေ့ပြဿနာကို ရှင်းပြပါ။ Record ရာချီသည် behavioral burst တစ်ခုတည်း ဖြစ်နိုင်သည်။ Grouping က ပြန့်ကျဲနေသော evidence ကို ပေါင်းပေးသည်။ Health monitoring က traffic မရှိသော sensor နှင့် ရပ်နေသော sensor ကို ခွဲပေးသည်။ Investigation note က browser ပိတ်သော်လည်း analyst ၏ သုံးသပ်ချက်ကို မပျောက်စေပါ။')
present.section('Architecture narration','ဖွဲ့စည်းပုံ ရှင်းပြရန်စကား')
present.pair('“There are two running services: the SSH sensor and the analyst dashboard. Incoming activity enters a bounded queue, then a worker writes normalized events to SQLite. The latest related behavioral session is recomputed, rules and the saved model are applied, and high-risk results update incidents. The browser requests changes every two seconds. It is near-real-time polling, not a hard real-time guarantee.”\n\nPoint out the trust boundary: the virtual shell can read its fake dictionary, not the host’s real filesystem. Explain that an operating SSH service and a simulated terminal can coexist: the transport is real, while the environment behind it is deliberately controlled.', '“Run နေသော service နှစ်ခုမှာ SSH sensor နှင့် analyst dashboard ဖြစ်သည်။ ဝင်လာသော activity ကို ကန့်သတ်ထားသော queue ထဲထည့်ပြီး worker က normalized event အဖြစ် SQLite တွင်သိမ်းသည်။ ဆက်စပ်နောက်ဆုံး session ကို ပြန်တွက်၊ rule နှင့် saved model အသုံးပြုပြီး high-risk result ကို incident တွင်ပြင်သည်။ Browser သည် နှစ်စက္ကန့်တစ်ကြိမ် ပြောင်းလဲမှုကိုတောင်းသည်။ Near-real-time polling ဖြစ်ပြီး hard real-time အာမခံချက် မဟုတ်ပါ။”\n\nTrust boundary ကို ထောက်ပြပါ။ Virtual shell က အတု dictionary ကိုသာဖတ်နိုင်ပြီး host file အစစ်ကို မဖတ်နိုင်ပါ။ SSH service အစစ်နှင့် terminal simulation သည် အတူရှိနိုင်ကြောင်း ရှင်းပြပါ။ Transport အစစ်ဖြစ်ပြီး နောက်ဘက် environment ကို ရည်ရွယ်ကန့်သတ်ထားခြင်းဖြစ်သည်။')
present.section('Technical contribution and conclusion','နည်းပညာဆိုင်ရာ ပါဝင်မှုနှင့် နိဂုံး')
present.pair('“The engineering contribution is the integration: stable live session IDs, privacy-aware normalization, a change feed that handles model rescoring, real sensor heartbeats and a persistent analyst workflow. The ML result supports reproducible rule-label agreement, but I do not claim it proves real-world attack accuracy. My next priorities are independent evaluation, durable telemetry and stronger incident/evidence integrity.”\n\nEnd with one concrete success criterion you actually demonstrated: an event became a session, the same session was updated, and an analyst note survived a page reload. Do not end only with a list of future features.', '“Engineering ပါဝင်မှုမှာ အစိတ်အပိုင်းချိတ်ဆက်ခြင်းဖြစ်သည်။ Live session ID မပြောင်းခြင်း၊ privacy ထည့်စဉ်းစားထားသော normalization၊ model ပြန်တွက်လျှင်လည်း ပြသနိုင်သော change feed၊ sensor heartbeat နှင့် အမြဲသိမ်းထားသော analyst workflow တို့ပါသည်။ ML ရလဒ်က rule label နှင့် ကိုက်ညီမှုကို ပြန်စမ်းနိုင်ကြောင်း ပံ့ပိုးသော်လည်း real-world attack accuracy ကို သက်သေပြသည်ဟု မဆိုပါ။ နောက်ဦးစားပေးများမှာ independent evaluation၊ durable telemetry နှင့် incident/evidence integrity ဖြစ်သည်။”\n\nနိဂုံးတွင် မိမိတကယ်ပြခဲ့သော အောင်မြင်မှုတစ်ခုကို ပြောပါ။ Event မှ session ဖြစ်လာခြင်း၊ session တူကို update လုပ်ခြင်းနှင့် page reload နောက် note ကျန်နေခြင်းတို့ကို ပြနိုင်သည်။ နောင်လုပ်မည့် feature စာရင်းဖြင့်သာ အဆုံးမသတ်ပါနှင့်။')

present.chapter('4. A safe dashboard demonstration, step by step','Dashboard လုပ်ဆောင်ပုံကို လုံခြုံစွာ အဆင့်ဆင့်ပြရန်')
present.pair('This demonstration covers the operator side only. If new network activity is required, arrange a separate, authorized lab exercise with the teacher beforehand. This guide does not tell anyone how to attack the port. Never substitute old imported events for live activity without saying so. If no approved traffic is available, demonstrate heartbeat, idle monitoring, existing evidence and incident management, clearly identifying historical data.', 'ဤ demo သည် operator ဘက်အတွက်သာဖြစ်သည်။ Network activity အသစ်လိုလျှင် ဆရာနှင့် ကြိုတင်ခွင့်ပြုထားသော သီးခြား lab exercise ကို စီစဉ်ပါ။ Port ကို တိုက်ခိုက်နည်း ဤလမ်းညွှန်တွင် မပါပါ။ Import လုပ်ထားသော event အဟောင်းကို live activity အဖြစ် မဖော်ပြပါနှင့်။ ခွင့်ပြုထားသော traffic မရှိလျှင် heartbeat၊ idle monitoring၊ ရှိပြီးသား evidence နှင့် incident management ကိုပြပြီး historical data ဖြစ်ကြောင်း ရှင်းပြပါ။')
present.table(['Step','Operator action / လုပ်ရန်','What to say / ပြောရန်'],[
('1','Start both services and sign in. / Service နှစ်ခုဖွင့်ပြီး login ဝင်။','“The management dashboard requires an analyst account.” / “Dashboard ဝင်ရန် analyst account လိုသည်။”'),('2','Open Live monitor; point at heartbeat/status. / Live monitor ၏ heartbeat/status ပြ။','“Online is based on sensor heartbeat, not just a loaded webpage.” / “Page ပေါ်ရုံမဟုတ်ဘဲ heartbeat ဖြင့် online သတ်မှတ်သည်။”'),('3','Choose sensor, severity and time window, then Apply. / Dropdown များရွေးပြီး Apply နှိပ်။','“Severity filters detections; raw events have no independent severity.” / “Severity က detection ကိုသာ filter လုပ်သည်။”'),('4','Observe approved new activity if available; otherwise state idle. / ခွင့်ပြု activity ရှိလျှင်ကြည့်၊ မရှိလျှင် idle ဟုပြော။','“These timestamps identify when evidence was received.” / “Timestamp များက event အချိန်ကို ဖော်ပြသည်။”'),('5','Open a detection/session and inspect count, label and evidence. / Detection/session ဖွင့်၍ count၊ label၊ evidence ကြည့်။','“Several records can belong to the same behavioral burst.” / “Record အများအပြားသည် burst တစ်ခုဖြစ်နိုင်သည်။”'),('6','Explain rule label, predicted label, final label and confidence separately. / Rule၊ prediction၊ final label နှင့် confidence ကိုခွဲရှင်း။','“The score is not a calibrated probability of maliciousness.” / “Score သည် အန္တရာယ်ရှိမှု၏ အတည်ပြု probability မဟုတ်ပါ။”'),('7','Open Incidents; choose a suitable existing record. / Incidents တွင် သင့်လျော်သော record ဖွင့်။','“High-risk live classifications create investigation records.” / “High-risk live classification မှ incident ဖန်တီးသည်။”'),('8','Set Investigating, add a clearly marked demo note, save and reload. / Investigating ပြောင်း၊ demo note ဟုရေး၊ save နှင့် reload လုပ်။','“The decision is stored, not merely painted on the page.” / “ဆုံးဖြတ်ချက်ကို page ပေါ်ပြရုံမဟုတ်ဘဲ သိမ်းထားသည်။”'),('9','Export CSV and inspect its scope without exposing sensitive values. / CSV ထုတ်၍ secret မဖော်ဘဲ အကျုံးဝင်မှုကိုပြ။','“This report is bounded to 5,000 evidence events.” / “ဤ report တွင် evidence event 5,000 အထိသာ ပါသည်။”'),('10','Show Pause/Resume; explain collection continues. / Pause/Resume ပြပြီး collection ဆက်လုပ်ကြောင်းရှင်း။','“Pause changes the view, not the sensor.” / “Pause က screen ကိုသာပြောင်းပြီး sensor မရပ်ပါ။”')],[650,4450,4400])
present.section('Optional operational proof: controlled stop and restart','ထပ်မံပြနိုင်သော စနစ်လုပ်ဆောင်မှုသက်သေ')
present.pair('With no active exercise in progress, stop only your own sensor from its terminal. Show that the dashboard remains accessible while the sensor goes offline. A normal shutdown may write offline promptly; if a heartbeat simply stops, the stale threshold is fifteen seconds plus polling delay. Restart the sensor and show a new heartbeat. This proves process-health visibility, not attack-detection performance. Do not crash the computer or corrupt the database for a classroom demonstration.', 'လက်ရှိ exercise မလုပ်နေချိန်တွင် မိမိ sensor ကိုသာ ၎င်း၏ terminal မှ ရပ်ပါ။ Dashboard ဝင်လို့ရနေသော်လည်း sensor offline ဖြစ်သွားသည်ကို ပြပါ။ ပုံမှန်ပိတ်လျှင် offline status ချက်ချင်းရေးနိုင်ပြီး heartbeat သာရပ်သွားလျှင် 15 စက္ကန့် threshold နှင့် polling delay နောက်တွင် stale ဖြစ်မည်။ Sensor ပြန်စပြီး heartbeat အသစ်ကို ပြပါ။ ဤအရာက process-health ကို မြင်နိုင်ကြောင်းသာ သက်သေပြပြီး attack detection performance ကိုမသက်သေပြပါ။ Demo အတွက် ကွန်ပျူတာ crash လုပ်ခြင်း သို့မဟုတ် database ဖျက်ဆီးခြင်း မလုပ်ပါနှင့်။')

present.chapter('5. Questions your teacher is likely to ask','ဆရာမေးနိုင်သော မေးခွန်းများနှင့် ဖြေဆိုပုံ')
qa=[
('What is original if you use AsyncSSH?','AsyncSSH supplies a standard protocol implementation. The project’s own logic supplies the decoy environment, event normalization, source/time grouping, feature extraction, labeling, live updates and investigation workflow. I should identify reused components honestly rather than claim original cryptography.','AsyncSSH က စံ protocol implementation ကိုပေးသည်။ Project ၏ ကိုယ်ပိုင် logic က decoy environment၊ normalization၊ grouping၊ feature၊ label၊ live update နှင့် investigation workflow ကိုပေးသည်။ ကိုယ်ပိုင် cryptography ဟုမဆိုဘဲ ပြန်သုံးထားသောအစိတ်အပိုင်းများကို မှန်ကန်စွာဖော်ပြရမည်။'),
('Are you using Cowrie or replacing Cowrie?','No Cowrie service is needed for live HoneyTrace operation. Cowrie logs can supply historical examples and a comparison baseline. This is a narrower self-built sensor with integrated analytics; it is not a demonstrated full replacement for Cowrie.','Live HoneyTrace အတွက် Cowrie service မလိုပါ။ Cowrie log ကို historical ဥပမာနှင့် comparison baseline အဖြစ်သုံးနိုင်သည်။ ဤစနစ်သည် analytics ချိတ်ထားသော scope ပိုကန့်သတ်သည့် ကိုယ်ပိုင် sensor ဖြစ်ပြီး Cowrie ကို အပြည့်အဝအစားထိုးနိုင်ကြောင်း မသက်သေပြထားပါ။'),
('Is it real or just a demo?','It accepts real SSH connections and stores real observations of those interactions. The command environment is intentionally simulated. “Real operation” does not mean executing untrusted code on the host. The current deployment scope is an isolated lab.','SSH connection အစစ်ကိုလက်ခံပြီး ထို interaction မှ observation အစစ်ကို သိမ်းသည်။ Command environment ကို ရည်ရွယ် simulation လုပ်ထားသည်။ အမှန်တကယ်အလုပ်လုပ်ခြင်းသည် မယုံကြည်ရသော code ကို host ပေါ် run ခြင်း မဟုတ်ပါ။ လက်ရှိအသုံးပြု scope သည် သီးခြား lab ဖြစ်သည်။'),
('Why not simply show the logs?','Raw logs are necessary but fragmented. Sessions summarize related behavior; rules provide an inspectable reason; revision updates show evolving evidence; incidents preserve analyst decisions and notes. The raw evidence remains available for checking the summary.','Raw log သည် လိုအပ်သော်လည်း ပြန့်ကျဲနေသည်။ Session က ဆက်စပ် behavior ကိုစု၊ rule က ရှင်းပြချက်ပေး၊ revision က evidence ပြောင်းလဲမှုကိုပြ၊ incident က analyst ဆုံးဖြတ်ချက်နှင့် note ကိုသိမ်းသည်။ အနှစ်ချုပ်ကိုစစ်ရန် raw evidence ကို ဆက်ကြည့်နိုင်သည်။'),
('Why use ML when rules generate labels?','At present ML is a learned approximation of a rule-labeled behavioral taxonomy. It demonstrates the training, selection and inference pipeline, but its added detection value over rules is not established. A fair next experiment compares rule-only, model-only and hybrid results on independently reviewed data.','လက်ရှိ ML သည် rule ဖြင့် label ပေးထားသော behavior အမျိုးအစားများကို သင်ယူထားခြင်းဖြစ်သည်။ Training၊ selection နှင့် inference pipeline ကိုပြနိုင်သော်လည်း rule ထက် detection တန်ဖိုးပိုရှိကြောင်း မသက်သေပြရသေးပါ။ နောက်စမ်းသပ်မှုတွင် လူကလွတ်လပ်စွာစစ်ထားသော data ပေါ်၌ rule-only၊ model-only နှင့် hybrid ကို နှိုင်းယှဉ်သင့်သည်။'),
('Does 99.44% mean 99.44% of attacks are caught?','No. The recorded balanced accuracy is agreement with pseudo-labels on the grouped holdout. It is the average class recall in that evaluation, not a universal detection rate or proof of malicious intent.','မဟုတ်ပါ။ မှတ်တမ်းတင်ထားသော balanced accuracy သည် grouped holdout ပေါ်ရှိ pseudo-label နှင့် ကိုက်ညီမှုဖြစ်သည်။ ထို evaluation ထဲမှ class recall ပျမ်းမျှဖြစ်ပြီး အားလုံးအတွက် detection rate သို့မဟုတ် မကောင်းသောရည်ရွယ်ချက်အတည်ပြုချက် မဟုတ်ပါ။'),
('How do you reduce data leakage?','Training and holdout separate groups defined by sensor and IP, and model selection occurs within the training partition. That reduces identity overlap at that granularity. It does not eliminate shared campaigns, the same IP across different sensors, or circularity from feature-derived labels.','Training နှင့် holdout ကို sensor/IP group အလိုက်ခွဲပြီး model ရွေးခြင်းကို training partition အတွင်းသာလုပ်သည်။ ထိုအဆင့်ရှိ identity ထပ်နေမှုကိုလျှော့သည်။ Campaign တူခြင်း၊ sensor မတူသော IP တူခြင်းနှင့် feature-derived label ကိုပြန်သင်ယူခြင်းကို မဖယ်နိုင်ပါ။'),
('Why Extra Trees?','The code compares Extra Trees and Random Forest on grouped cross-validation macro-F1. Extra Trees was selected in the recorded run. I should say it performed better in that particular comparison, not that it is always the best classifier.','Code က Extra Trees နှင့် Random Forest ကို grouped cross-validation macro-F1 ဖြင့်နှိုင်းသည်။ မှတ်တမ်းတင်ထားသော run တွင် Extra Trees ကိုရွေးခဲ့သည်။ ထိုနှိုင်းယှဉ်မှုတွင် ပိုကောင်းခဲ့သည်ဟုသာပြောပြီး အမြဲတမ်းအကောင်းဆုံး classifier ဟုမဆိုသင့်ပါ။'),
('How is the final label chosen?','Unknown-rule sessions remain unscored. For other sessions, the highest model score is used if it is at least 0.55; below that, the rule label remains final. This is a fixed heuristic, not a calibrated threshold validated for a production cost model.','Rule အရ unknown ဖြစ်လျှင် score မတွက်ပါ။ အခြား session များတွင် model score အများဆုံးက 0.55 နှင့်အထက်လျှင် ထို label ကိုယူပြီး မပြည့်လျှင် rule label ကိုယူသည်။ ၎င်းသည် production cost model အတွက် validate လုပ်ထားသော calibrated threshold မဟုတ်ဘဲ fixed heuristic ဖြစ်သည်။'),
('Can the model discover a completely new attack?','Not reliably by design. It predicts among its trained classes and has no general novelty detector. Unknown-rule sessions are unscored; other unsupported behavior may be mapped to a known class. Novel-attack discovery is future research, not an implemented guarantee.','ဒီဇိုင်းအရ ယုံကြည်စိတ်ချစွာ မရှာနိုင်ပါ။ Training class ထဲမှသာ ခန့်မှန်းပြီး general novelty detector မရှိပါ။ Unknown-rule session ကို score မတွက်သော်လည်း အခြား unsupported behavior ကို known class သို့ခွဲနိုင်သည်။ Attack အသစ်ရှာခြင်းသည် နောင်သုတေသနဖြစ်ပြီး လက်ရှိအာမခံချက် မဟုတ်ပါ။'),
('Is the confidence the chance that this person is malicious?','No. It is the highest class score from predict_proba, not a calibrated probability of maliciousness and not evidence about a verified person. The interface should be interpreted alongside the raw observations and rule reason.','မဟုတ်ပါ။ predict_proba မှ class score အများဆုံးသာဖြစ်ပြီး malicious ဖြစ်နိုင်ခြေအတွက် calibrated probability မဟုတ်ပါ။ အတည်ပြုထားသောလူတစ်ဦးအကြောင်း သက်သေလည်းမဟုတ်ပါ။ Raw observation နှင့် rule reason တို့နှင့်အတူ သုံးသပ်ရမည်။'),
('What exactly is real time here?','The sensor records continuously while running, and the browser normally polls every two seconds. Processing, queue backlog and network delay add latency. I call it near-real-time monitoring and would measure event-to-display delay before promising a service target.','Sensor run နေစဉ် အဆက်မပြတ်မှတ်တမ်းတင်ပြီး browser က ပုံမှန်နှစ်စက္ကန့်တစ်ကြိမ်မေးသည်။ Processing၊ backlog နှင့် network delay ကြောင့် အချိန်ထပ်ကြာနိုင်သည်။ Near-real-time monitoring ဟုခေါ်ပြီး service target မကတိပေးမီ event-to-display delay တိုင်းသင့်သည်။'),
('Do you train again every day?','No. Daily operation loads the saved model and performs inference. Retraining is deliberate maintenance for changed data, features or labels. A missing artifact gives rule-only live analysis; a fresh GitHub clone does not include the private trained model.','မလိုပါ။ နေ့စဉ်အသုံးပြုရာတွင် saved model ကိုဖတ်ပြီး inference လုပ်သည်။ Data၊ feature သို့မဟုတ် label ပြောင်းမှ ရည်ရွယ် retraining လုပ်သည်။ Artifact မရှိလျှင် live analysis ကို rule-only ဖြင့်လုပ်ပြီး GitHub clone အသစ်တွင် private trained model မပါပါ။'),
('Are passwords safely handled?','Normalized events store keyed fingerprints and masked previews instead of reusable plaintext password values. However raw values briefly exist in memory, previews expose some information, and command text can contain secrets. The database is sensitive and must remain protected.','Normalized event တွင် plaintext password အစား keyed fingerprint နှင့် masked preview သိမ်းသည်။ သို့သော် raw value သည် memory တွင်ခဏရှိ၊ preview က အချက်အလက်အချို့ပြပြီး command text တွင် secret ပါနိုင်သည်။ Database ကို sensitive data အဖြစ် ကာကွယ်ရမည်။'),
('Can an attacker use this as a real shell or proxy?','The implemented terminal only accesses in-memory fake files. There is no subprocess execution; SFTP and forwarding are denied. This substantially narrows the intended capability, but protocol-library bugs and resource exhaustion remain reasons for isolation and patching.','ရေးထားသော terminal သည် memory ထဲရှိ file အတုကိုသာသုံးသည်။ Subprocess execution မရှိ၊ SFTP နှင့် forwarding ကိုငြင်းသည်။ အသုံးချနိုင်သောစွမ်းရည်ကို ကျဉ်းစေသော်လည်း protocol library bug နှင့် resource exhaustion အတွက် isolation နှင့် patching လိုနေဆဲဖြစ်သည်။'),
('Does it block attacks on other computers?','No. It observes interactions directed to the honeypot. It is not a network-wide intrusion-prevention system, endpoint antivirus or automatic firewall controller. It can complement those controls by providing decoy telemetry.','မလုပ်ပါ။ Honeypot သို့ရောက်သော interaction ကိုသာ လေ့လာသည်။ Network-wide intrusion-prevention၊ endpoint antivirus သို့မဟုတ် automatic firewall controller မဟုတ်ပါ။ Decoy telemetry ပေးခြင်းဖြင့် ထိုစနစ်များကို ဖြည့်စွက်ကူညီနိုင်သည်။'),
('Why SQLite?','It makes a local project easy to run and inspect, and WAL supports concurrent reading while data is written. The tradeoff is a single-file, limited-write-concurrency design. A distributed production deployment would need a measured storage and ingestion redesign.','Local project ကို ဖွင့်ရန်နှင့်စစ်ရန် လွယ်ကူပြီး WAL က data ရေးနေစဉ် ဖတ်ခြင်းကိုကူညီသည်။ အပြန်အလှန်ကန့်သတ်ချက်မှာ file တစ်ခုအခြေခံနှင့် write concurrency နည်းခြင်းဖြစ်သည်။ Distributed production အတွက် storage/ingestion ကို တိုင်းတာပြီး ပြန်ဒီဇိုင်းလုပ်ရန်လိုသည်။'),
('What happens when the queue fills or the process crashes?','A full queue increments a dropped-event counter and closes the relevant client. Failed batches have three total attempts. The queue is not durable: a crash can lose uncommitted events. Monitoring makes some failures visible but does not guarantee lossless capture.','Queue ပြည့်လျှင် dropped-event counter တိုးပြီး သက်ဆိုင်ရာ client ကိုပိတ်သည်။ Failed batch ကို စုစုပေါင်းသုံးကြိမ်ကြိုးစားသည်။ Queue သည် durable မဟုတ်သဖြင့် crash လျှင် မသိမ်းရသေးသော event ပျောက်နိုင်သည်။ Monitoring က ချို့ယွင်းမှုအချို့ကိုပြနိုင်သော်လည်း data မပျောက်ဟု အာမမခံပါ။'),
('Can I use it in an organization now?','It can be piloted in an authorized isolated environment with clear limits. I would not put it on a public production network without independent evaluation, hardening, monitoring, backups, retention, HTTPS management and a response owner. No production certification is claimed.','ခွင့်ပြုထားသော သီးခြား environment တွင် ကန့်သတ်ချက်ရှင်းရှင်းဖြင့် pilot လုပ်နိုင်သည်။ Independent evaluation၊ hardening၊ monitoring၊ backup၊ retention၊ HTTPS management နှင့် တာဝန်ရှိသူမရှိဘဲ public production network ပေါ်မထားသင့်ပါ။ Production certification ရှိသည်ဟု မဆိုပါ။'),
('What would you improve first?','First, independent reviewed labels and live-sensor evaluation. Second, durable event handling and evidence integrity. Third, safer rule/model fusion and deployment security. These improve trustworthiness more than adding decorative dashboard panels.','ပထမ independent reviewed label နှင့် live-sensor evaluation၊ ဒုတိယ durable event handling နှင့် evidence integrity၊ တတိယ rule/model ပေါင်းစပ်ပုံနှင့် deployment security ကို ဦးစားပေးမည်။ ဤအရာများက dashboard အလှအပ panel ထပ်ထည့်ခြင်းထက် စနစ်ကို ယုံကြည်နိုင်မှု ပိုတိုးစေသည်။')]
for i,(q,e,m) in enumerate(qa,1):
    present.section(f'Q{i}. {q}',f'မေးခွန်း {i} — ဖြေဆိုရန်')
    present.pair(e,m)

present.chapter('6. Explain it to someone with basic IT knowledge','အခြေခံ IT သိသူကို နားလည်လွယ်စွာ ရှင်းပြရန်')
present.section('Use an analogy, then explain where it stops','ဥပမာပေးပြီး ဥပမာ၏ကန့်သတ်ချက်ကို ရှင်းပြရန်')
present.pair('“Imagine a building with an empty display room, a visitor log and a receptionist. HoneyTrace’s decoy service is the display room: it looks usable but contains no real business files. The sensor is the observer, the database is the logbook, the grouping logic combines related visits, and the dashboard is the receptionist’s screen. An incident is a case folder with notes.”\n\nThen correct the analogy: HoneyTrace is not watching the entire building or every computer on the network. It sees only interactions reaching its own decoy service. A suspicious pattern is a reason to review the case, not proof that every visitor is a criminal.', '“အဆောက်အအုံတစ်ခုတွင် ပစ္စည်းအစစ်မရှိသော ပြခန်း၊ ဧည့်သည်မှတ်တမ်းစာအုပ်နှင့် ဧည့်ကြိုတစ်ဦးရှိသည်ဟု စဉ်းစားပါ။ HoneyTrace ၏ decoy service က ပြခန်းနှင့်တူသည်။ အသုံးပြုလို့ရသလိုထင်ရသော်လည်း လုပ်ငန်းဖိုင်အစစ်မရှိပါ။ Sensor က စောင့်ကြည့်သူ၊ database က မှတ်တမ်းစာအုပ်၊ grouping logic က ဆက်စပ်လာရောက်မှုများကိုပေါင်းသူ၊ dashboard က ဧည့်ကြိုကြည့်သော screen ဖြစ်သည်။ Incident က note ပါသော case folder ဖြစ်သည်။”\n\nထို့နောက် ဥပမာကို ပြန်ကန့်သတ်ပါ။ HoneyTrace သည် အဆောက်အအုံတစ်ခုလုံး သို့မဟုတ် network ရှိ computer အားလုံးကို စောင့်ကြည့်နေခြင်း မဟုတ်ပါ။ မိမိ decoy service သို့ရောက်သော interaction ကိုသာမြင်သည်။ သံသယပုံစံသည် case ကိုပြန်စစ်ရန် အကြောင်းရင်းဖြစ်ပြီး လာသူတိုင်း ရာဇဝတ်သားဖြစ်ကြောင်း သက်သေမဟုတ်ပါ။')
present.section('Five-minute plain-IT speaking script','အခြေခံ IT ပရိသတ်အတွက် ငါးမိနစ်ခန့် ပြောရန်')
present.pair('“You already know that a server can accept a remote login. SSH is one way to do that securely over a network. HoneyTrace opens an SSH service intentionally, but the environment behind the login is a decoy. It does not contain our real documents or give access to the Windows computer running the project.\n\nWhen someone connects or submits a login, the system records an event. An event is just one observation. Many observations may belong together, so HoneyTrace groups them by source and time. Think of the difference between individual entries in a logbook and one complete story about a visit.\n\nNext, it summarizes the story with numbers. How many logins failed? How many different usernames appeared? Were commands submitted? Did the command text contain certain indicators? Rules use those numbers to suggest a behavior category. A trained model also looks for patterns it learned earlier. Neither the rules nor the model can read someone’s mind, and neither proves malicious intent by itself.\n\nOn the screen, the live monitor shows recent events and whether the sensor is running. A high-risk result can become an incident. The person reviewing it can read the evidence, write a note, change the investigation status and download a report. That is the useful part: turning separate technical records into an organized investigation.\n\nThe project does not scan every computer, remove viruses or automatically block people. It gives an IT team another source of observations from a decoy. This version is designed for a controlled lab, and the remaining work is to measure it more rigorously and improve reliability before wider deployment.”', '“Server တစ်ခုကို အဝေးမှ login ဝင်နိုင်သည်ကို သိပြီးဖြစ်ပါမည်။ SSH သည် network ပေါ်တွင် လုံခြုံစွာ remote login လုပ်နိုင်သောနည်းတစ်ခုဖြစ်သည်။ HoneyTrace က SSH service ကို ရည်ရွယ်ဖွင့်ထားသော်လည်း login နောက်ဘက် environment သည် အတုဖြစ်သည်။ မိမိတို့၏ document အစစ်များမရှိသလို project run နေသော Windows computer ကို ဝင်သုံးခွင့်လည်း မပေးပါ။\n\nတစ်ယောက်ယောက် ချိတ်ဆက်ခြင်း သို့မဟုတ် login ပေးပို့ခြင်းလုပ်လျှင် system က event မှတ်တမ်းတင်သည်။ Event ဆိုသည်မှာ observation တစ်ခုသာဖြစ်သည်။ Observation များစွာသည် ဆက်စပ်နိုင်သောကြောင့် HoneyTrace က source နှင့် အချိန်အလိုက် အုပ်စုဖွဲ့သည်။ မှတ်တမ်းစာအုပ်ထဲရှိ စာကြောင်းတစ်ကြောင်းစီနှင့် ဧည့်သည်လာရောက်မှုတစ်ခုလုံး၏ အကြောင်းအရာကို ခွဲစဉ်းစားသလိုဖြစ်သည်။\n\nထို့နောက် အကြောင်းအရာကို ကိန်းဂဏန်းဖြင့် အနှစ်ချုပ်သည်။ Login ဘယ်နှစ်ကြိမ်မအောင်မြင်သလဲ။ Username ဘယ်နှမျိုးရှိသလဲ။ Command ပေးပို့ခဲ့သလား။ Command စာသားထဲတွင် သတ်မှတ် indicator ပါသလား။ Rule များက ထိုကိန်းများဖြင့် behavior အမျိုးအစားကို အကြံပြုသည်။ လေ့ကျင့်ထားသော model ကလည်း ယခင်သင်ထားသည့် pattern ကိုကြည့်သည်။ Rule နှင့် model နှစ်ခုလုံးက လူတစ်ဦး၏စိတ်ကို မဖတ်နိုင်သလို တစ်ခုတည်းဖြင့် မကောင်းသောရည်ရွယ်ချက်ကို မသက်သေပြနိုင်ပါ။\n\nScreen ပေါ်ရှိ live monitor တွင် လတ်တလော event နှင့် sensor အလုပ်လုပ်နေမှုကို မြင်ရသည်။ High-risk result သည် incident ဖြစ်လာနိုင်သည်။ စစ်ဆေးသူက evidence ဖတ်၊ note ရေး၊ investigation status ပြောင်းပြီး report ထုတ်နိုင်သည်။ နည်းပညာ record သီးခြားများကို စနစ်တကျစုံစမ်းစစ်ဆေးမှုအဖြစ် ပြောင်းနိုင်ခြင်းက အသုံးဝင်သောအချက်ဖြစ်သည်။\n\nProject က computer အားလုံးကို scan လုပ်ခြင်း၊ virus ဖယ်ခြင်း သို့မဟုတ် လူများကို အလိုအလျောက် block လုပ်ခြင်း မလုပ်ပါ။ IT team အတွက် decoy မှ observation ရနိုင်သော နောက်ထပ်ရင်းမြစ်တစ်ခုဖြစ်သည်။ လက်ရှိ version သည် controlled lab အတွက်ဖြစ်ပြီး ပိုကျယ်ပြန့်စွာအသုံးမပြုမီ စနစ်တကျတိုင်းတာခြင်းနှင့် reliability တိုးတက်ခြင်း လုပ်ရန်ကျန်သည်။”')
present.section('What to show, and what to skip','ပြသင့်သောအရာနှင့် ချန်ထားသင့်သောအရာ')
present.pair('Show just three screens: Live monitor, one Session and one Incident. Explain online/offline, related records and a saved note. Skip tree hyperparameters, SQL schema and all 31 feature names unless asked. Replace “inference” with “using a model already trained”; replace “telemetry” with “recorded observations”; replace “pseudo-label agreement” with “how closely the model matches the project’s rule-based examples”. Keep the accuracy disclaimer, but explain it in one clear sentence.', 'Screen သုံးခုသာ အဓိကပြပါ။ Live monitor၊ Session တစ်ခုနှင့် Incident တစ်ခုဖြစ်သည်။ Online/offline၊ record ဆက်စပ်မှုနှင့် save ထားသော note ကိုရှင်းပြပါ။ မမေးလျှင် tree hyperparameter၊ SQL schema နှင့် feature 31 ခုအမည်အားလုံးကို မဖတ်ပြပါနှင့်။ Inference ကို လေ့ကျင့်ပြီးသား model အသုံးပြုခြင်း၊ telemetry ကို မှတ်တမ်းတင်ထားသော observation၊ pseudo-label agreement ကို project rule ပေးထားသော ဥပမာများနှင့် model ဘယ်လောက်ကိုက်သလဲဟု အစားထိုးပြောပါ။ Accuracy သတိပြုချက်ကို မဖယ်ဘဲ ရှင်းသောဝါကျတစ်ကြောင်းဖြင့် ပြောပါ။')

present.chapter('7. Common questions from a basic-IT audience','အခြေခံ IT ပရိသတ် မေးတတ်သောမေးခွန်းများ')
simple=[
('Is it a fake website?','No. The decoy target is an SSH remote-login service. The website-like screen is the analyst dashboard used to inspect it.','မဟုတ်ပါ။ Decoy target သည် SSH remote-login service ဖြစ်သည်။ Website လိုမြင်ရသော screen က analyst ကြည့်ရန် dashboard ဖြစ်သည်။'),
('Will it protect my laptop automatically?','Not by itself. It observes its decoy service and helps investigation. Normal patching, endpoint protection, access control and backups are still needed.','သူတစ်ခုတည်းဖြင့် မကာကွယ်ပေးပါ။ Decoy service ကိုကြည့်ပြီး investigation ကူညီသည်။ ပုံမှန် patching၊ endpoint protection၊ access control နှင့် backup လိုနေဆဲဖြစ်သည်။'),
('Why let somebody log in?','Only the decoy environment is accessible. Allowing controlled interaction reveals behavior that a rejected connection alone cannot show. It must remain isolated from real data.','Decoy environment ကိုသာ ဝင်နိုင်သည်။ ကန့်သတ် interaction လက်ခံခြင်းက connection ငြင်းပယ်ရုံဖြင့်မမြင်ရသော behavior ကိုမြင်စေသည်။ Real data နှင့် သီးခြားထားရမည်။'),
('Does a red warning mean confirmed damage?','No. It means the project’s classification assigned high priority. The evidence may be a submitted keyword or pattern, not successful damage to a real computer.','မဟုတ်ပါ။ Project classification က ဦးစားပေးအဆင့်မြင့် သတ်မှတ်ထားခြင်းဖြစ်သည်။ Evidence သည် keyword သို့မဟုတ် pattern ဖြစ်နိုင်ပြီး computer အစစ် ပျက်စီးသွားခြင်း မဟုတ်ပါ။'),
('Why can I see complete source addresses?','The analyst view shows complete IPs by default so evidence can be correlated. Optional masking is available for shared screens, but the underlying database still contains the address and must be protected.','Evidence ကိုဆက်စပ်စစ်ဆေးနိုင်ရန် analyst view တွင် IP အပြည့်အစုံကို ပုံမှန်ပြသည်။ Screen မျှဝေရာတွင် optional masking ဖွင့်နိုင်သော်လည်း database ထဲတွင် IP အစစ်ရှိနေသဖြင့် ကာကွယ်ထားရမည်။'),
('If the screen shows zero, is it broken?','Not necessarily. There may be no recent traffic, or a filter may hide it. Check sensor heartbeat and the selected time window before deciding.','မဟုတ်နိုင်ပါ။ လတ်တလော traffic မရှိခြင်း သို့မဟုတ် filter ကြောင့် မပြခြင်းဖြစ်နိုင်သည်။ Sensor heartbeat နှင့် time window ကိုအရင်စစ်ပါ။'),
('Do I need to keep the browser open?','No for collection, yes if you want to watch the display. The sensor process must remain running; the dashboard process must run for browser access.','Collection အတွက် browser ဖွင့်ထားရန်မလိုဘဲ screen ကြည့်လိုမှလိုသည်။ Sensor process ဆက် run နေရမည်။ Browser မှဝင်ရန် dashboard process လည်း run နေရမည်။'),
('Will it learn automatically as more people connect?','Not in this version. It uses a saved model. New training is a separate planned operation after data review.','ဤ version တွင် အလိုအလျောက်မသင်ပါ။ Saved model ကိုသုံးသည်။ Data ပြန်စစ်ပြီးမှ training အသစ်ကို သီးခြားလုပ်ရသည်။')]
for q,e,m in simple:
    present.section(q,'နားလည်လွယ်သော အဖြေ')
    present.pair(e,m)

present.chapter('8. Claims to use and claims to avoid','ပြောသင့်သောအဆိုနှင့် ရှောင်သင့်သောအဆို')
present.table(['Avoid / မပြောသင့်','Use instead / အစားထိုးပြောရန်'],[
('“It detects 99% of real attacks.”\n“တကယ့် attack 99% ဖမ်းနိုင်သည်။”','“The recorded model closely matches rule-generated labels on grouped holdout data.”\n“မှတ်တမ်းရှိ model က grouped holdout ပေါ်တွင် rule label နှင့် ကောင်းစွာကိုက်ညီသည်။”'),
('“It is better than Cowrie.”\n“Cowrie ထက်ပိုကောင်းသည်။”','“It implements my chosen sensor-and-analysis workflow; a controlled comparison is still needed.”\n“ရွေးထားသော sensor/analysis workflow ကိုလုပ်ထားပြီး controlled comparison လိုသေးသည်။”'),
('“It executes attacker commands safely.”\n“တိုက်ခိုက်သူ command ကို လုံခြုံစွာ run သည်။”','“It records submitted commands and returns simulated responses without host execution.”\n“Command ကိုမှတ်တမ်းတင်ပြီး host ပေါ်မလုပ်ဘဲ အတုအဖြေပြန်သည်။”'),
('“All passwords are encrypted.”\n“Password အားလုံး encrypt လုပ်ထားသည်။”','“Event passwords become keyed fingerprints; analyst passwords use scrypt hashes. Raw values briefly exist in memory.”\n“Event password ကို fingerprint၊ analyst password ကို scrypt hash လုပ်သည်။ Raw value က memory တွင်ခဏရှိသည်။”'),
('“Every suspicious IP is an attacker.”\n“သံသယ IP တိုင်း attacker ဖြစ်သည်။”','“The IP is a source indicator, not a verified person or intent.”\n“IP သည် source indicator ဖြစ်ပြီး လူနှင့်ရည်ရွယ်ချက် အတည်ပြုချက်မဟုတ်ပါ။”'),
('“The dashboard is real time with no delay.”\n“Dashboard က delay မရှိသော real time ဖြစ်သည်။”','“It normally polls every two seconds, plus processing delay.”\n“ပုံမှန်နှစ်စက္ကန့်တစ်ကြိမ် polling နှင့် processing delay ရှိသည်။”'),
('“This is industry-ready.”\n“လုပ်ငန်းသုံးအဆင်သင့်ဖြစ်သည်။”','“This is a working lab implementation with operational features and documented production gaps.”\n“Operational feature ပါသော အလုပ်လုပ်သည့် lab implementation ဖြစ်ပြီး production ကွာဟချက်ရှိသည်။”'),
('“It learns by itself every day.”\n“နေ့တိုင်း အလိုအလျောက်သင်သည်။”','“It reuses a saved model; retraining is separate.”\n“Saved model ပြန်သုံးပြီး retraining သည် သီးခြားဖြစ်သည်။”')],[4200,5300])

present.chapter('9. Fair evaluation and teacher evidence pack','မျှတသော evaluation နှင့် ဆရာကိုပြရန် evidence အစု')
present.pair('Prepare evidence before presenting: the exact code commit, a simple architecture page, a screenshot with timestamps and a clearly identified data source, one linked session/incident, a redacted CSV sample, test output, and the saved model evaluation disclaimer. Use dummy lab identifiers only. Label every screenshot as live observation, historical import or illustrative fixture. Do not mix those three sources under one “live attacks” heading.', 'တင်ပြမီ evidence ပြင်ထားပါ။ Code commit အတိအကျ၊ ရိုးရှင်းသော architecture စာမျက်နှာ၊ timestamp နှင့် source ရှင်းသော screenshot၊ ဆက်စပ် session/incident တစ်ခု၊ sensitive data ဖုံးထားသော CSV ဥပမာ၊ test output နှင့် model evaluation disclaimer တို့ဖြစ်သည်။ Dummy lab identifier ကိုသာသုံးပါ။ Screenshot တိုင်းကို live observation၊ historical import သို့မဟုတ် illustrative fixture ဟုသတ်မှတ်ပါ။ သုံးမျိုးလုံးကို live attacks ခေါင်းစဉ်တစ်ခုတည်းအောက် မရောပါနှင့်။')
present.table(['Question to evaluate','Suggested measurement / တိုင်းတာရန်အကြံပြုချက်'],[
('Does collection work? / Collection အလုပ်လုပ်သလား။','Compare expected observations with stored normalized events for a small approved exercise. / ခွင့်ပြု exercise အသေးတစ်ခု၏ မျှော်မှန်း event နှင့် သိမ်းထားသော event ကိုနှိုင်း။'),('How quickly does it display? / ဘယ်လောက်မြန်မြန်ပြသလဲ။','Measure event timestamp to visible update; report median and 95th percentile, hardware and sample count. / Event အချိန်မှ screen update အထိတိုင်း၊ median၊ 95th percentile၊ hardware နှင့် sample count ပြ။'),('Does grouping help? / Grouping အသုံးဝင်သလား။','Show event count versus session/incident count for the same observation period. / အချိန်တူအတွင်း event count နှင့် session/incident count နှိုင်း။'),('Is classification trustworthy? / Classification ယုံကြည်ရသလား။','Use independently reviewed labels and report confusion matrix and per-class precision/recall. / လွတ်လပ်စွာစစ်ထားသော label ဖြင့် confusion matrix နှင့် class အလိုက် precision/recall ပြ။'),('Is the hybrid better than rules? / Hybrid က rule ထက်ကောင်းသလား။','Compare rules only, model only and hybrid on the same held-out data. / Holdout data တူပေါ်တွင် rules-only၊ model-only နှင့် hybrid နှိုင်း။'),('Does it remain operational? / ဆက်လက်အလုပ်လုပ်နိုင်သလား။','Record backlog, drop counter, CPU/memory and recovery after a planned restart. / Backlog၊ drop၊ CPU/memory နှင့် စီစဉ် restart နောက် recovery ကိုမှတ်။'),('How does it compare to Cowrie? / Cowrie နှင့် ဘယ်လိုနှိုင်းမလဲ။','Use a documented baseline version/configuration and equal authorized scenarios; separate realism, analytics and workflow. / Baseline version/config မှတ်တမ်းတင်ပြီး scenario တူသုံး၊ realism၊ analytics နှင့် workflow ခွဲနှိုင်း။')],[3500,6000])
present.note('These are proposed evaluation activities, not benchmark results already completed. Leave results blank until measured. Honest experimental design is more impressive than invented numbers.','ဤအရာများသည် evaluation လုပ်ရန် အကြံပြုချက်ဖြစ်ပြီး ပြီးစီးပြီးသား benchmark result မဟုတ်ပါ။ မတိုင်းရသေးသော ရလဒ်ကို အလွတ်ထားပါ။ အမှန်တကယ်စမ်းသပ်ရန် ဒီဇိုင်းကောင်းခြင်းသည် ကိန်းဂဏန်းဖန်တီးပြခြင်းထက် ပိုတန်ဖိုးရှိသည်။')

present.chapter('10. Handling a failed demonstration','Demo မအောင်မြင်ချိန် ကိုင်တွယ်ပုံ')
present.pair('If the sensor is offline: “The dashboard is working, but the sensor heartbeat is absent. That is why I keep process health separate from the event chart. I will check the sensor terminal and configuration.” If approved live traffic is unavailable: “I can demonstrate current service health and stored investigation evidence, but I will not call historical data a live capture.” If the model is missing: “The sensor can still produce rule-based classifications; this checkout does not contain the private model artifact.”', 'Sensor offline ဖြစ်လျှင် “Dashboard အလုပ်လုပ်သော်လည်း sensor heartbeat မရှိပါ။ ဒါကြောင့် process health ကို event chart နှင့်ခွဲထားခြင်းဖြစ်သည်။ Sensor terminal နှင့် configuration ကိုစစ်ပါမည်” ဟုပြောပါ။ ခွင့်ပြုထားသော live traffic မရှိလျှင် “လက်ရှိ service health နှင့် သိမ်းထားသော investigation evidence ကိုပြနိုင်သော်လည်း historical data ကို live capture ဟု မခေါ်ပါ” ဟုပြောပါ။ Model မရှိလျှင် “Sensor သည် rule-based classification ဆက်လုပ်နိုင်ပြီး ဤ checkout တွင် private model artifact မပါပါ” ဟုပြောပါ။')
present.pair('Keep a clearly labeled backup evidence set and an offline copy of the source/run guide. A screenshot proves what was visible when captured, not that the system is live now. Do not disable login, expose the dashboard publicly or invent traffic just to rescue a presentation. If an error cannot be fixed quickly, explain which subsystem failed, what evidence remains and the next diagnostic step. That demonstrates engineering judgment.', 'ရှင်းလင်းစွာ label တပ်ထားသော backup evidence နှင့် offline source/run guide ကိုထားပါ။ Screenshot သည် ရိုက်ခဲ့ချိန်တွင် မြင်ရသောအရာ၏ သက်သေသာဖြစ်ပြီး ယခု live ဖြစ်ကြောင်း မသက်သေပြပါ။ Presentation ကယ်ရန် login ပိတ်ခြင်း၊ dashboard public ဖွင့်ခြင်း သို့မဟုတ် traffic ဖန်တီးပြောခြင်း မလုပ်ပါနှင့်။ Error ကို အမြန်မပြင်နိုင်လျှင် ဘယ် subsystem ပျက်သည်၊ ဘယ် evidence ကျန်သည်၊ နောက်စစ်မည့်အဆင့် ဘာလဲဟု ရှင်းပြပါ။ ထိုသို့ရှင်းပြနိုင်ခြင်းက engineering ဆုံးဖြတ်နိုင်မှုကိုပြသည်။')

present.chapter('11. Bilingual terminology and useful phrases','ဘာသာနှစ်မျိုး နည်းပညာဝေါဟာရနှင့် အသုံးဝင်သောစကားများ')
present.table(['English','မြန်မာရှင်းလင်းချက်'],[
('SSH','Network ပေါ်မှ encrypted remote login လုပ်နိုင်သော protocol။'),('Decoy','အစစ်ဟုထင်ရစေရန် ရည်ရွယ်ထားသော အတုအရာ။'),('Honeypot','ဝင်ရောက်မှုများကိုလေ့လာရန်ထားသော decoy service။'),('Telemetry','စနစ်က မှတ်တမ်းတင်ပေးသော လုပ်ဆောင်မှုအချက်အလက်။'),('Normalization','ပုံစံမတူသော input ကို schema တစ်မျိုးတည်းသို့ ပြောင်းခြင်း။'),('Deduplication','တူညီသော record ကို ထပ်မသိမ်းရန်စစ်ခြင်း။'),('Sessionization','ဆက်စပ် event များကို source နှင့်အချိန်အလိုက် အုပ်စုဖွဲ့ခြင်း။'),('Feature','Model သို့ထည့်သော ကိန်းဂဏန်းအချက်။'),('Rule / heuristic','သတ်မှတ်ထားသော စည်းမျဉ်း သို့မဟုတ် အနီးစပ်ဆုံးအကဲဖြတ်နည်း။'),('Pseudo-label','Rule မှထုတ်ပေးသော label၊ independent truth မဟုတ်။'),('Ground truth','Evaluation အတွက် လွတ်လပ်စွာစစ်ဆေးအတည်ပြုထားသော reference label။'),('Training','ဥပမာ data များမှ model ၏ ဆုံးဖြတ်ပုံကိုသင်ယူခြင်း။'),('Inference','လေ့ကျင့်ပြီးသား model ဖြင့် input အသစ်ကိုခန့်မှန်းခြင်း။'),('Holdout','Model ရွေးခြင်း/သင်ခြင်းတွင် မသုံးဘဲ သီးခြားစမ်းရန်ထားသော data။'),('Data leakage','Evaluation အဖြေကိုသိသလိုဖြစ်စေသော train/test အချက်အလက်ရောနှောမှု။'),('False positive','အန္တရာယ်မရှိသောအရာကို အန္တရာယ်ရှိသည်ဟု မှားသတ်မှတ်ခြင်း။'),('False negative','အန္တရာယ်ရှိသောအရာကို လွတ်သွားခြင်း။'),('Domain shift','Training data နှင့် အသုံးပြုချိန် data ပုံစံကွာခြားခြင်း။'),('Heartbeat','Sensor အသက်ဝင်နေကြောင်း ပုံမှန်ပို့သော အချက်ပြ။'),('Backlog','Queue ထဲတွင် မလုပ်ဆောင်ရသေးဘဲ စောင့်နေသောအလုပ်။'),('Incident','စုံစမ်းစစ်ဆေးရန် သီးခြားသိမ်းထားသော case မှတ်တမ်း။'),('Containment','မယုံကြည်ရသောလုပ်ဆောင်ချက်ကို သတ်မှတ်နယ်နိမိတ်အတွင်း ထိန်းခြင်း။'),('Authentication / authorization','ဘယ်သူဖြစ်ကြောင်းစစ်ခြင်း / ဘာလုပ်ခွင့်ရှိကြောင်းသတ်မှတ်ခြင်း။'),('CSRF protection','Login ဝင်ထားသော browser ကို အခြားနေရာမှ လှည့်စား၍ write request ပို့ခြင်းကို ကာကွယ်ရန် token စစ်ခြင်း။')],[2900,6600])
present.pair('Useful transitions: “Let me separate what is observed from what is inferred.” “This is implemented; the next item is future work.” “The evidence supports a narrower claim.” “The recorded score measures label agreement, not intent.” “I have not measured that yet; here is how I would test it.”', 'ချိတ်ဆက်ပြောရန် အသုံးဝင်သောစကားများ — “တကယ်တွေ့ထားသောအရာနှင့် ခန့်မှန်းထားသောအရာကို ခွဲရှင်းပါမည်။” “ဒါက လက်ရှိလုပ်ထားပြီးသားဖြစ်ပြီး နောက်အချက်က နောင်လုပ်ရန်ဖြစ်သည်။” “Evidence အရ ဒီထက်ကန့်သတ်သောအဆိုကိုသာ ပြောနိုင်ပါသည်။” “မှတ်တမ်းရှိ score က label ကိုက်ညီမှုကို တိုင်းပြီး ရည်ရွယ်ချက်ကို မတိုင်းပါ။” “အဲဒီအချက်ကို မတိုင်းရသေးပါ။ စမ်းသပ်မည့်နည်းကတော့ ဒီလိုဖြစ်ပါသည်။”')

present.chapter('12. Final rehearsal checklist and closing statement','နောက်ဆုံးလေ့ကျင့်စစ်ဆေးရန်နှင့် အဆုံးသတ်စကား')
present.table(['Check','What must be ready / အဆင်သင့်ဖြစ်ရမည့်အရာ'],[
('Understanding','Explain the six-stage pipeline without reading code. / Code မဖတ်ဘဲ pipeline ခြောက်ဆင့် ရှင်းနိုင်။'),('Evidence','Know which records are live, historical or fixtures. / Live၊ historical နှင့် fixture ကိုခွဲသိ။'),('Ownership','Name reused libraries and your actual contribution honestly. / Library နှင့် မိမိတကယ်ပါဝင်မှုကို မှန်ကန်စွာပြောနိုင်။'),('Access','Own analyst login works; no real password shown on slides. / Analyst login ဝင်နိုင်ပြီး slide တွင် password မပါ။'),('Services','Sensor and dashboard start separately; heartbeat is current. / Service နှစ်ခု သီးခြားဖွင့်နိုင်ပြီး heartbeat လတ်ဆတ်။'),('Model','Understand saved-model reuse and pseudo-label limitations. / Saved model နှင့် pseudo-label ကန့်သတ်ချက်နားလည်။'),('Investigation','Can open a session, save a note and inspect a bounded export. / Session ဖွင့်၊ note သိမ်း၊ export စစ်နိုင်။'),('Safety','Authorized isolated lab; no public exposure or attacker instructions included. / ခွင့်ပြုသီးခြား lab၊ public ဖွင့်ခြင်းနှင့် attack ညွှန်ကြားချက်မပါ။'),('Recovery','Have clearly labeled backup evidence and know the first diagnostic step. / Label တပ်ထားသော backup evidence နှင့် ပထမစစ်မည့်အဆင့်သိ။'),('Honesty','Can state three current limitations without undermining the working contribution. / လက်ရှိကန့်သတ်ချက်သုံးခုနှင့် အလုပ်လုပ်သောတန်ဖိုးကို ခွဲပြောနိုင်။')],[2200,7300])
present.section('Closing statement','အဆုံးသတ်ပြောရန်')
present.pair('“HoneyTrace demonstrates a complete defensive workflow: observe, organize, classify and investigate. Its live SSH transport and persistent evidence show that it is more than a static dashboard, while the contained terminal keeps the experiment separate from the real host. The strongest result is an explainable working pipeline. The next step is to validate it with independent labels and improve reliability before wider deployment.”', '“HoneyTrace သည် စောင့်ကြည့်ခြင်း၊ စုစည်းခြင်း၊ အမျိုးအစားခွဲခြင်းနှင့် စုံစမ်းစစ်ဆေးခြင်းတို့ပါသော defensive workflow တစ်ခုလုံးကို ပြသသည်။ Live SSH transport နှင့် အမြဲသိမ်းထားသော evidence ကြောင့် static dashboard ထက်ပိုသော အလုပ်လုပ်သည့်စနစ်ဖြစ်ပြီး contained terminal က စမ်းသပ်မှုကို host အစစ်မှခွဲထားသည်။ အခိုင်မာဆုံးရလဒ်မှာ ရှင်းပြနိုင်ပြီး အလုပ်လုပ်သော pipeline ဖြစ်သည်။ နောက်တစ်ဆင့်မှာ independent label များဖြင့်စစ်ဆေးပြီး ပိုကျယ်ပြန့်စွာမသုံးမီ reliability ကို တိုးတက်စေရန်ဖြစ်သည်။”')
present.pair('Reference companion: HoneyTrace_Technical_Guide_EN_MY.docx contains exact rules, all features, implementation limits and file/API details. The source reference is commit 4d97809. Treat this presentation guide as preparation material, not a claim that the original academic reports have already been updated.', 'တွဲဖက်ဖတ်ရန် HoneyTrace_Technical_Guide_EN_MY.docx တွင် rule အတိအကျ၊ feature အားလုံး၊ implementation ကန့်သတ်ချက်နှင့် file/API အသေးစိတ်ပါသည်။ Source reference သည် commit 4d97809 ဖြစ်သည်။ ဤ presentation guide သည် ပြင်ဆင်လေ့ကျင့်ရန်ဖြစ်ပြီး မူရင်းကျောင်းတင် report များကို ပြင်ပြီးသားဟု မဆိုလိုပါ။')

tech.chapter('20. Worked example: from five observations to one case','Observation ငါးခုမှ case တစ်ခုအထိ တွက်ချက်ပြသည့် ဥပမာ')
tech.pair('This is an illustrative explanation of already-recorded observations, not a new measured test or a traffic-generation procedure. Assume one source, one sensor and one native SSH connection. Use the rule-only path first so each intermediate decision is explicit.', 'ဤဥပမာသည် မှတ်တမ်းတင်ပြီးသော observation များကို ရှင်းပြရန် စိတ်ကူးဥပမာသာဖြစ်ပြီး အသစ်တိုင်းတာထားသော test သို့မဟုတ် traffic ထုတ်လုပ်ရန်လုပ်ငန်းစဉ် မဟုတ်ပါ။ Source တစ်ခု၊ sensor တစ်ခုနှင့် native SSH connection တစ်ခုဟု ယူဆပါ။ အဆင့်တိုင်း၏ ဆုံးဖြတ်ချက်ရှင်းစေရန် ပထမဦးစွာ rule-only လမ်းကြောင်းကိုသုံးပါ။')
